/**
 * Veilpay Logo Component
 * Reusable logo component for consistent branding across the app
 * 
 * Usage:
 * - <Logo variant="full" /> - Full Veilpay logo with text (uses Veilpay.png)   
 * - <Logo variant="icon" /> - Icon only (shield logo from Logo.png)
 * - <Logo variant="header" /> - Compact icon version for headers
 * - <Logo variant="manual" /> - Shield icon + Manually written text
 */import React from 'react';import { View, Image, StyleSheet, Text, ViewStyle, TextStyle, ImageStyle } from 'react-native';
import { useTheme, useStyles, typography, spacing, type Colors } from "../styles/design-tokens";

export type LogoVariant = 'full' | 'icon' | 'header' | 'manual';

interface LogoProps {
  variant?: LogoVariant;
  style?: ViewStyle;
  size?: 'small' | 'medium' | 'large';
  textStyle?: TextStyle;
  imageStyle?: ImageStyle;
}

export function Logo({ 
  variant = 'full', 
  style, 
  size = 'medium',
  textStyle,
  imageStyle
}: LogoProps) { 
  const { theme, colors } = useTheme();
  const styles = useStyles(themeStyles);
  
  const iconSource = theme === 'dark' ? require('../../assets/logo-icon-dark.png') : require('../../assets/logo-icon.png');
  const fullSource = theme === 'dark' ? require('../../assets/logo-full-dark.png') : require('../../assets/logo-full.png');
  
  // Size configurations for different variants
  const sizeConfig = {
    small: {
      icon: 24,
      full: 100,
      header: 28,
      fontSize: 20,
    },
    medium: {
      icon: 40,
      full: 140,
      header: 36,
      fontSize: 28,
    },
    large: {
      icon: 64,
      full: 200,
      header: 56,
      fontSize: 36,
    },
  };

  const currentSize = sizeConfig[size];

  // Render manual variant: Logo icon + Manually written VEILPAY text
  if (variant === 'manual') {
    return (
      <View style={[styles.manualContainer, style]}>
        <Image
          source={iconSource}
          style={[{ width: currentSize.icon, height: currentSize.icon }, imageStyle]}
          resizeMode="contain"
        />
        <Text style={[
          styles.manualText,
          { fontSize: currentSize.fontSize },
          textStyle
        ]}>
          VEILPAY
        </Text>
      </View>
    );
  }

  // Render icon only (Logo.png - shield icon)
  if (variant === 'icon') {
    return (
      <View style={[styles.iconContainer, style]}>
        <Image
          source={iconSource}
          style={[{ width: currentSize.icon, height: currentSize.icon }, imageStyle]}
          resizeMode="contain"
        />
      </View>
    );
  }

  // Render full logo (Veilpay.png - full name logo) or header icon
  const logoSize = variant === 'full' ? currentSize.full : currentSize.header;  

  return (
    <View style={[styles.container, style]}>
      <Image
        source={fullSource}
        style={[{ width: logoSize, height: logoSize * 0.3 }, imageStyle]}
        resizeMode="contain"
      />
    </View>
  );
}

const themeStyles = (colors: Colors) => StyleSheet.create({
  container: {
    alignItems: 'center',
    justifyContent: 'center',
  },
  iconContainer: {
    alignItems: 'center',
    justifyContent: 'center',
  },
  manualContainer: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'center',
    gap: spacing[3],
  },
  manualText: {
    fontFamily: typography.fontFamily.headlineBold,
    color: colors.textPrimary,
    letterSpacing: 2,
  },
});

export default Logo;

import React from 'react';
import { SvgXml } from 'react-native-svg';

/**
 * Brand-official network icons sourced from @web3icons/core (Apache-2.0).
 *
 * Each chain points at one of the maintainer's branded SVG strings; we render
 * them via react-native-svg's <SvgXml> so we don't need a Metro transformer.
 * The component API is intentionally identical to the previous in-house set:
 * `getNetworkIcon(chainKey)` returns a Component accepting `{ size }`, and
 * each per-chain icon (EthereumIcon, BaseIcon, ...) is exported by name.
 *
 * Why @web3icons/core instead of inline path data:
 *   - Logos are sourced from each chain's brand kit, not redrawn from memory.
 *   - Updates ship upstream when chains rebrand, no app PR required.
 *   - One canonical mark per chain; matches what other wallets show today.
 *
 * Why <SvgXml> rather than the svg-transformer Metro plugin:
 *   - Zero Metro config changes.
 *   - The `.svg.js` files in @web3icons/core export the raw SVG markup as a
 *     plain string default export, which SvgXml renders directly.
 */

import branded_ethereum from '@web3icons/core/svgs/networks/branded/ethereum.svg.js';
import branded_base from '@web3icons/core/svgs/networks/branded/base.svg.js';
import branded_arbitrum from '@web3icons/core/svgs/networks/branded/arbitrum-one.svg.js';
import branded_optimism from '@web3icons/core/svgs/networks/branded/optimism.svg.js';
import branded_polygon from '@web3icons/core/svgs/networks/branded/polygon.svg.js';
import branded_bnb from '@web3icons/core/svgs/networks/branded/binance-smart-chain.svg.js';
import branded_solana from '@web3icons/core/svgs/networks/branded/solana.svg.js';
import branded_bitcoin from '@web3icons/core/svgs/networks/branded/bitcoin.svg.js';
import branded_tron from '@web3icons/core/svgs/networks/branded/tron.svg.js';
import branded_avalanche from '@web3icons/core/svgs/networks/branded/avalanche.svg.js';
import branded_linea from '@web3icons/core/svgs/networks/branded/linea.svg.js';
import branded_aptos from '@web3icons/core/svgs/networks/branded/aptos.svg.js';
import branded_stellar from '@web3icons/core/svgs/networks/branded/stellar.svg.js';
import branded_hyperevm from '@web3icons/core/svgs/networks/branded/hyper-evm.svg.js';

export interface NetworkIconProps {
  size?: number;
}

/**
 * Build a per-chain icon Component from a brand-official SVG string. The
 * resulting component renders at any caller-provided pixel size; the
 * underlying SVG keeps its native viewBox and scales proportionally.
 */
function makeBrandedIcon(svg: string) {
  const Icon = ({ size = 24 }: NetworkIconProps) => (
    <SvgXml xml={svg} width={size} height={size} />
  );
  return Icon;
}

export const EthereumIcon = makeBrandedIcon(branded_ethereum);
export const BaseIcon = makeBrandedIcon(branded_base);
export const ArbitrumIcon = makeBrandedIcon(branded_arbitrum);
export const OptimismIcon = makeBrandedIcon(branded_optimism);
export const PolygonIcon = makeBrandedIcon(branded_polygon);
export const BnbIcon = makeBrandedIcon(branded_bnb);
export const SolanaIcon = makeBrandedIcon(branded_solana);
export const BitcoinIcon = makeBrandedIcon(branded_bitcoin);
export const TronIcon = makeBrandedIcon(branded_tron);
export const AvalancheIcon = makeBrandedIcon(branded_avalanche);
export const LineaIcon = makeBrandedIcon(branded_linea);
export const AptosIcon = makeBrandedIcon(branded_aptos);
export const StellarIcon = makeBrandedIcon(branded_stellar);
export const HyperEVMIcon = makeBrandedIcon(branded_hyperevm);

/**
 * Neutral compass fallback for unknown chains. Stays inline so we never crash
 * on a chainKey that isn't covered by @web3icons/core.
 */
const DEFAULT_NETWORK_SVG = `
<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 32 32" fill="none">
  <rect width="32" height="32" rx="10" fill="#3A3A3C"/>
  <circle cx="16" cy="16" r="6" stroke="#FFFFFF" stroke-width="2" fill="none"/>
  <path d="M16 5V9M16 23V27M5 16H9M23 16H27M8.5 8.5L11.5 11.5M20.5 20.5L23.5 23.5M23.5 8.5L20.5 11.5M11.5 20.5L8.5 23.5"
    stroke="#FFFFFF" stroke-width="1.5" stroke-linecap="round"/>
</svg>
`;
export const DefaultNetworkIcon = makeBrandedIcon(DEFAULT_NETWORK_SVG);

export const getNetworkIcon = (chainKey: string) => {
  const normalized = chainKey.toLowerCase();
  switch (normalized) {
    case 'ethereum':
    case 'eth':
    case 'sepolia':
      return EthereumIcon;
    case 'linea':
      return LineaIcon;
    case 'base':
      return BaseIcon;
    case 'arbitrum':
    case 'arb':
    case 'arbitrum-one':
      return ArbitrumIcon;
    case 'bsc':
    case 'bnb':
    case 'bnb chain':
    case 'binance-smart-chain':
      return BnbIcon;
    case 'optimism':
    case 'op':
      return OptimismIcon;
    case 'polygon':
    case 'matic':
      return PolygonIcon;
    case 'bitcoin':
    case 'btc':
      return BitcoinIcon;
    case 'solana':
    case 'sol':
    case 'solana-devnet':
    case 'solana-mainnet':
      return SolanaIcon;
    case 'tron':
    case 'trx':
      return TronIcon;
    case 'avalanche':
    case 'avax':
      return AvalancheIcon;
    case 'aptos':
    case 'aptos-mainnet':
      return AptosIcon;
    case 'stellar':
    case 'stellar-mainnet':
    case 'stellar-testnet':
    case 'xlm':
      return StellarIcon;
    case 'hyperevm':
    case 'hyperliquid':
    case 'hyper-evm':
      return HyperEVMIcon;
    default:
      return DefaultNetworkIcon;
  }
};

import React from 'react';
import { Modal, TouchableOpacity, View, Text, StyleSheet, TextInput, ScrollView } from 'react-native';
import { triggerLightImpactHaptic } from '../utils/haptics';
import { SovereignCard } from './SovereignCard';
import { Icon } from './Icon';
import { getNetworkIcon } from './NetworkIcons';
import { typography, useTheme, useStyles, type Colors } from "../styles/design-tokens";
import type { ChainConfig } from '../stores/walletStore';

interface NetworkSelectorModalProps {
  visible: boolean;
  activeChain: ChainConfig | null;
  chains: ChainConfig[];
  onSelect: (chain: ChainConfig) => void;
  onClose: () => void;
  title?: string;
}

export function NetworkSelectorModal({
  visible,
  activeChain,
  chains = [],
  onSelect,
  onClose,
  title = 'SELECT NETWORK',
}: NetworkSelectorModalProps) {
  const { colors } = useTheme();
  const styles = useStyles(themeStyles);
  const [searchQuery, setSearchQuery] = React.useState('');

  const { mainnets, testnets } = React.useMemo(() => {
    const query = searchQuery.toLowerCase().trim();
    const filtered = chains.filter(chain => 
      !query || 
      chain.name.toLowerCase().includes(query) || 
      chain.symbol.toLowerCase().includes(query) ||
      chain.type.toLowerCase().includes(query)
    );

    return {
      mainnets: filtered.filter(c => !c.isTestnet),
      testnets: filtered.filter(c => !!c.isTestnet)
    };
  }, [chains, searchQuery]);
  
  // Reset search when modal opens
  React.useEffect(() => {
    if (visible) setSearchQuery('');
  }, [visible]);
  
  return (
    <Modal 
      visible={visible} 
      transparent 
      animationType="slide" 
      onRequestClose={onClose}
    >
      <View style={styles.overlay}>
        <TouchableOpacity 
          style={StyleSheet.absoluteFill} 
          activeOpacity={1} 
          onPress={onClose} 
        />
        <View style={styles.content}>
          <View style={styles.handle} />
          <View style={styles.header}>
            <Text style={styles.title}>{title}</Text>
            <TouchableOpacity
              onPress={onClose}
              style={styles.closeButton}
            >
              <Icon name="close" size={20} color={colors.textMuted} />
            </TouchableOpacity>
          </View>

          {/* Premium Search Bar */}
          <View style={styles.searchContainer}>
            <Icon name="search" size={18} color={colors.textTertiary} />
            <TextInput
              style={styles.searchInput}
              placeholder="Search networks or tokens..."
              placeholderTextColor={colors.textFaint}
              value={searchQuery}
              onChangeText={setSearchQuery}
              selectionColor={colors.accent}
              autoCorrect={false}
              returnKeyType="search"
            />
          </View>

          {/* Network Selection Warning */}
          <View style={styles.warningBanner}>
            <Icon name="info" size={16} color={colors.warning} />
            <Text style={styles.warningText}>
              Ensure your destination address is on the same network to avoid permanent loss of funds.
            </Text>
          </View>

          <ScrollView style={styles.listContainer} showsVerticalScrollIndicator={false}>
            {mainnets.length > 0 && (
              <View style={styles.section}>
                <View style={styles.sectionHeader}>
                  <Text style={styles.sectionHeaderText}>PRODUCTION MAINNETS</Text>
                  <View style={styles.sectionLine} />
                </View>
                {mainnets.map((chain) => (
                  <ChainItem 
                    key={chain.key} 
                    chain={chain} 
                    selected={activeChain?.key === chain.key} 
                    onSelect={onSelect} 
                    styles={styles} 
                    colors={colors} 
                  />
                ))}
              </View>
            )}

            {testnets.length > 0 && (
              <View style={styles.section}>
                <View style={styles.sectionHeader}>
                  <Text style={styles.sectionHeaderText}>DEVELOPMENT TESTNETS</Text>
                  <View style={styles.sectionLine} />
                </View>
                {testnets.map((chain) => (
                  <ChainItem 
                    key={chain.key} 
                    chain={chain} 
                    selected={activeChain?.key === chain.key} 
                    onSelect={onSelect} 
                    styles={styles} 
                    colors={colors} 
                  />
                ))}
              </View>
            )}

            {mainnets.length === 0 && testnets.length === 0 && (
              <View style={styles.emptyState}>
                <Text style={styles.emptyText}>No results found for "{searchQuery}"</Text>
              </View>
            )}
            <View style={{ height: 40 }} />
          </ScrollView>
        </View>
      </View>
    </Modal>
  );
}

// Sub-component for individual chain items to keep the main modal clean
function ChainItem({ chain, selected, onSelect, styles, colors }: any) {
  const getDisplayType = (chain: any) => {
    if (chain.key === 'arbitrum' || chain.key === 'polygon') return 'L2 NETWORK';
    if (chain.key === 'bsc') return 'BNB CHAIN';
    if (chain.type === 'evm') return 'EVM NETWORK';
    if (chain.type === 'svm') return 'SVM NETWORK';
    if (chain.type === 'mvm') return 'MVM NETWORK';
    if (chain.type === 'xlm') return 'STELLAR NETWORK';
    return 'NETWORK';
  };

  return (
    <TouchableOpacity
      onPress={() => {
        triggerLightImpactHaptic();
        onSelect(chain);
      }}
      activeOpacity={0.85}
      style={styles.chainRow}
    >
      <View style={[
        styles.chainItem,
        selected && styles.chainItemActive
      ]}>
        <View style={[
          styles.chainIconContainer,
          selected && styles.chainIconContainerActive
        ]}>
          {(() => {
            const NetworkIconSVG = getNetworkIcon(chain.key);
            return <NetworkIconSVG size={38} />;
          })()}
        </View>
        <View style={styles.chainMainInfo}>
          <Text style={[
            styles.chainName, 
            selected && styles.chainNameActive
          ]}>
            {chain.name.toUpperCase()}
          </Text>
          <Text style={[
            styles.chainType, 
            selected && styles.chainTypeActive
          ]}>
            {getDisplayType(chain)}
          </Text>
        </View>
        <View style={styles.chainRightInfo}>
          <Text style={[
            styles.chainSymbol, 
            selected && styles.chainSymbolActive
          ]}>
            {chain.symbol}
          </Text>
          {selected && (
            <View style={styles.activeIndicator}>
              <Icon name="success" size={14} color={colors.bgPrimary} />
            </View>
          )}
        </View>
      </View>
    </TouchableOpacity>
  );
}

