import React, { useCallback } from "react";
import { View, Text, StyleSheet, Pressable, StyleProp, ViewStyle, TextStyle } from "react-native";
import { typography, useTheme, useStyles, type Colors } from "../styles/design-tokens";
import { triggerLightImpactHaptic } from "../utils/haptics";
import Animated, { useAnimatedStyle, useSharedValue, withSpring, runOnJS } from "react-native-reanimated";

interface SovereignButtonProps {
  title?: string;
  onPress?: () => void;
  style?: StyleProp<ViewStyle>;
  textStyle?: TextStyle;
  variant?: "primary" | "secondary" | "outline" | "danger";
  disabled?: boolean;
  shape?: "pill" | "rounded";
  accessibilityLabel?: string;
  accessibilityHint?: string;
  children?: React.ReactNode;
}

/**
 * SovereignButton (The Sovereign Minimalist)
 * Elegant typography with subtle press animation. No neo-brutalist offsets.
 * Manrope for headlines, Inter for body.
 */
export function SovereignButton({
  title,
  onPress,
  style,
  textStyle,
  variant = "primary",
  disabled = false,
  shape = "pill",
  accessibilityLabel,
  accessibilityHint,
  children,
}: SovereignButtonProps) {
  const { colors } = useTheme();
  const styles = useStyles(themeStyles);
  const isPressed = useSharedValue(false);

  const borderRadius = shape === "pill" ? 9999 : 16;

  const getBackgroundColor = () => {
    if (disabled) return colors.bgContainerHigh;
    if (variant === "primary") return colors.accent;
    if (variant === "secondary") return colors.bgTertiary;
    if (variant === "danger") return colors.error + "20";
    return "transparent";
  };

  const getTextColor = () => {
    if (disabled) return colors.textTertiary;
    if (variant === "primary") return colors.bgPrimary;
    if (variant === "danger") return colors.error;
    if (variant === "outline" || variant === "secondary") return colors.textPrimary;
    return colors.textPrimary;
  };

  const springConfig = { mass: 1, stiffness: 400, damping: 25 };

  const animatedStyle = useAnimatedStyle(() => {
    const targetScale = isPressed.value ? 0.95 : 1;
    const targetOpacity = isPressed.value ? 0.8 : 1;
    
    const scale = withSpring(targetScale, springConfig, (finished) => {
      // Fire haptic at the exact moment the button reaches its maximum compression (bottom out)
      if (finished && targetScale === 0.95) {
        runOnJS(triggerLightImpactHaptic)();
      }
    });
    
    return {
      transform: [{ scale }],
      opacity: withSpring(targetOpacity, { ...springConfig, damping: 20 }),
    };
  });

  const handlePressIn = useCallback(() => {
    if (disabled) return;
    isPressed.value = true;
    // Haptic is now physics-driven in the spring callback above
  }, [disabled, isPressed]);

  const handlePressOut = useCallback(() => {
    isPressed.value = false;
  }, [isPressed]);

  return (
    <Pressable
      onPressIn={handlePressIn}
      onPressOut={handlePressOut}
      onPress={onPress}
      style={[styles.buttonWrapper, style]}
      disabled={disabled}
      accessibilityRole="button"
      accessibilityLabel={accessibilityLabel || title}
      accessibilityHint={accessibilityHint}
      accessibilityState={disabled ? { disabled: true } : undefined}
    >
      <Animated.View
        style={[
          styles.buttonSurface,
          animatedStyle,
          {
            backgroundColor: getBackgroundColor(),
            borderRadius,
            borderWidth: 0,
            paddingHorizontal: children ? 0 : 24,
          },
        ]}
      >
        {children || (
          <Text style={[styles.buttonText, { color: getTextColor() }, textStyle]}>
            {title}
          </Text>
        )}
      </Animated.View>
    </Pressable>
  );
}

const themeStyles = (colors: Colors) => StyleSheet.create({
  buttonWrapper: {
    position: "relative",
    width: "100%",
  },
  buttonSurface: {
    width: "100%",
    height: 56,
    justifyContent: "center",
    alignItems: "center",
  },
  buttonText: {
    fontFamily: typography.fontFamily.headlineBold,
    fontSize: 16,
    letterSpacing: 0.5,
  },
});

import React, { useCallback } from "react";
import { View, StyleSheet, Pressable, ViewStyle, AccessibilityRole, Platform } from "react-native";
import Animated, { useAnimatedStyle, useSharedValue, withSpring, runOnJS } from "react-native-reanimated";
import { useTheme, useStyles, type Colors } from "../styles/design-tokens";
import { triggerLightImpactHaptic } from "../utils/haptics";

interface SovereignCardProps {
  children: React.ReactNode;
  style?: ViewStyle;
  padding?: number;
  backgroundColor?: string;
  onPress?: () => void;
  borderColor?: string;
  borderRadius?: number;
  /** Defaults to 'button' when onPress is provided */
  accessibilityRole?: AccessibilityRole;
  accessibilityLabel?: string;
  accessibilityHint?: string;
  /** Disable haptic feedback for high-frequency presses (e.g. lists) */
  disableHaptic?: boolean;
}

// Reuse spring config object to avoid re-allocation on every render
const SPRING_CONFIG = { mass: 1, stiffness: 400, damping: 25 };

/**
 * SovereignCard (The Sovereign Minimalist)
 * Custom tactile spring-press animation when clickable and soft premium ambient occlusion shadows.
 * No borders, pure tonal layering with spatial separation.
 */
export function SovereignCard({
  children,
  style,
  padding = 24,
  backgroundColor,
  onPress,
  borderColor = "transparent",
  borderRadius = 24,
  accessibilityRole: accessibilityRoleProp,
  accessibilityLabel,
  accessibilityHint,
  disableHaptic,
}: SovereignCardProps) {
  const { colors } = useTheme();
  const styles = useStyles(themeStyles);
  const isPressed = useSharedValue(false);
  const actualBackgroundColor = backgroundColor === undefined ? colors.bgTertiary : backgroundColor;

  const animatedStyle = useAnimatedStyle(() => {
    const scale = withSpring(isPressed.value ? 0.98 : 1, SPRING_CONFIG);
    return {
      transform: [{ scale }],
    };
  });

  const handlePressIn = useCallback(() => {
    if (!onPress) return;
    isPressed.value = true;
    if (!disableHaptic) {
      // Use runOnJS to safely call haptic from worklet context
      runOnJS(triggerLightImpactHaptic)();
    }
  }, [onPress, isPressed, disableHaptic]);

  const handlePressOut = useCallback(() => {
    isPressed.value = false;
  }, [isPressed]);

  const content = (
    <View
      style={[
        styles.cardSurface,
        style,
        {
          padding,
          backgroundColor: actualBackgroundColor,
          borderColor,
          borderRadius,
        },
      ]}
    >
      {children}
    </View>
  );

  if (onPress) {
    return (
      <Pressable
        onPressIn={handlePressIn}
        onPressOut={handlePressOut}
        onPress={onPress}
        accessibilityRole={accessibilityRoleProp ?? 'button'}
        accessibilityLabel={accessibilityLabel}
        accessibilityHint={accessibilityHint}
        style={styles.clickableWrapper}
      >
        <Animated.View style={[animatedStyle, styles.fullWidth]}>
          {content}
        </Animated.View>
      </Pressable>
    );
  }

  return content;
}

const themeStyles = (colors: Colors) => StyleSheet.create({
  clickableWrapper: {
    width: "100%",
  },
  fullWidth: {
    width: "100%",
  },
  cardSurface: {
    width: "100%",
    justifyContent: "center",
    // Use a subtle border on Android to avoid harsh elevation shadows and opacity animation bugs.
    // On iOS, use an extremely soft ambient shadow.
    ...(Platform.OS === 'ios'
      ? {
          borderWidth: 0,
          borderColor: "transparent",
          shadowColor: "#000000",
          shadowOffset: { width: 0, height: 4 },
          shadowOpacity: 0.04,
          shadowRadius: 12,
        }
      : {
          elevation: 0,
          borderWidth: 1,
          borderColor: colors.outlineSubtle,
        }),
  },
});

/**
 * Veilpay Toast Component
 * Hybrid structural toast notifications for user feedback
 *
 * UPDATED: Now uses premium SVG icons
 */

import React, { useEffect, useRef, useState } from 'react';
import {
  View,
  Text,  StyleSheet,  Animated,  TouchableOpacity,
} from 'react-native';
import { typography, useTheme, useStyles, type Colors } from "../styles/design-tokens";
import { Icon, IconName } from './Icon';

export type ToastType = 'success' | 'error' | 'info' | 'warning';

interface ToastProps {
  visible: boolean;
  message: string;
  type?: ToastType;
  duration?: number;
  onDismiss: () => void;
}

const getToastConfig = (colors: Colors): Record<ToastType, { iconName: IconName; bgColor: string; shadowColor: string; textColor: string }> => ({
  success: {
    iconName: 'success',
    bgColor: colors.successMuted,
    shadowColor: colors.successMuted,
    textColor: colors.textPrimary,
  },
  error: {
    iconName: 'error',
    bgColor: colors.error,
    shadowColor: colors.error,
    textColor: colors.textPrimary,
  },
  info: {
    iconName: 'info',
    bgColor: colors.bgTertiary,
    shadowColor: colors.accent,
    textColor: colors.textPrimary,
  },
  warning: {
    iconName: 'warning',
    bgColor: colors.accent,
    shadowColor: colors.accent,
    textColor: colors.textPrimary,
  },
});

export function Toast({
  visible,
  message,
  type = 'info',
  duration = 3000,
  onDismiss,
}: ToastProps) {
  const { colors } = useTheme();
  const styles = useStyles(themeStyles);
  const translateY = useRef(new Animated.Value(100)).current;
  const opacity = useRef(new Animated.Value(0)).current;
  const config = getToastConfig(colors)[type];

  useEffect(() => {
    if (visible) {
      Animated.parallel([
        Animated.spring(translateY, {
          toValue: 0,
          useNativeDriver: true,
          tension: 100,
          friction: 10,
        }),
        Animated.timing(opacity, {
          toValue: 1,
          duration: 200,
          useNativeDriver: true,
        }),
      ]).start();

      const timer = setTimeout(() => {
        handleDismiss();
      }, duration);

      return () => clearTimeout(timer);
    } else {      translateY.setValue(100);
      opacity.setValue(0);
    }  }, [visible, duration]);

  const handleDismiss = () => {
    Animated.parallel([
      Animated.timing(translateY, {
        toValue: 100,
        duration: 200,
        useNativeDriver: true,
      }),
      Animated.timing(opacity, {
        toValue: 0,
        duration: 200,
        useNativeDriver: true,
      }),
    ]).start(() => {
      onDismiss();
    });
  };

  if (!visible) return null;

  return (
    <Animated.View
      style={[
        styles.container,
        {
          transform: [{ translateY }],
          opacity,
        },
      ]}
      accessibilityLiveRegion="polite"
    >
      <TouchableOpacity
        activeOpacity={0.9}
        onPress={handleDismiss}
        style={styles.touchable}
        accessibilityRole="button"
        accessibilityLabel="Dismiss notification"
        accessibilityHint="Closes this toast message"
      >
        {/* Shadow layer */}
        <View style={[styles.shadow, { backgroundColor: config.shadowColor }]} />
        
        {/* Surface layer */}
        <View style={[styles.surface, { backgroundColor: config.bgColor }]}>
          <View style={styles.iconBox}>
            <Icon name={config.iconName} size={18} color={config.textColor} />
          </View>
          <Text style={[styles.message, { color: config.textColor }]}>
            {message}
          </Text>
        </View>
      </TouchableOpacity>
    </Animated.View>
  );
}

const themeStyles = (colors: Colors) => StyleSheet.create({
  container: {    position: 'absolute',
    bottom: 24,
    left: 24,
    right: 24,    zIndex: 1000,
  },
  touchable: {
    width: '100%',
    minHeight: 44,
    justifyContent: 'center',
  },
  shadow: {
    position: 'absolute',
    top: 4,
    left: 4,
    right: 0,
    bottom: 0,
    borderWidth: 0,
    borderColor: 'transparent',
  },
  surface: {
    flexDirection: 'row',
    alignItems: 'center',
    padding: 16,
    borderWidth: 0,
    borderColor: 'transparent',
    gap: 12,
  },
  iconBox: {
    width: 28,
    height: 28,
    alignItems: 'center',
    justifyContent: 'center',
  },
  icon: {
    fontSize: 16,
    fontWeight: 'bold',
  },
  message: {
    flex: 1,
    fontFamily: typography.fontFamily.mono,
    fontSize: 14,
    fontWeight: 'bold',
    letterSpacing: 0.5,
  },
});

// Hook for easy toast usage

interface UseToastReturn {
  visible: boolean;
  message: string;
  type: ToastType;
  show: (msg: string, toastType?: ToastType) => void;
  hide: () => void;
}

export function useToast(): UseToastReturn {
  const [visible, setVisible] = useState(false);
  const [message, setMessage] = useState('');
  const [type, setType] = useState<ToastType>('info');

  const show = (msg: string, toastType: ToastType = 'info') => {
    setMessage(msg);
    setType(toastType);
    setVisible(true);
  };

  const hide = () => {
    setVisible(false);
  };

  return { visible, message, type, show, hide };
}

export default Toast;

import React, { memo } from 'react';
