                style={[styles.typeIcon, { backgroundColor: isSent ? colors.errorBg : colors.successBg }]}
              >
                <Icon name={isSent ? 'send' : 'receive'} size={16} color={colors.textPrimary} />
              </Animated.View>
              <View style={styles.transactionInfo}>
