 onError?: (error: Error) => void;
};

const DEFAULT_INTERVAL_MS = 30000;

export function useBalancePolling(options: UseBalancePollingOptions = {}) {
 const {
 intervalMs = DEFAULT_INTERVAL_MS,
 enabled = true,
 initialFetch = true,
 onBalanceUpdate,
 onError,
 } = options;

 const address = useWalletAddress();
 const activeChain = useActiveChain();
 const setBalance = useWalletStore((state) => state.setBalance);
 const setLoadingBalance = useWalletStore((state) => state.setLoadingBalance);

 const [status, setStatus] = useState<BalancePollingStatus>({
 balance: null,
 balanceUsd: null,
 isLoading: false,
 error: null,
 lastUpdated: null,
 isStale: true,
 });

 const isMountedRef = useRef(true);
 const intervalIdRef = useRef<ReturnType<typeof setInterval> | null>(null);
 const isPollingRef = useRef(false);

 useEffect(() => {
 isMountedRef.current = true;
 return () => {
 isMountedRef.current = false;
 };
 }, []);

 const fetchBalance = useCallback(async () => {
 if (!address || !activeChain || !isMountedRef.current) {
 return;
 }

 if (!isMountedRef.current) return;

 setStatus((prev) => ({ ...prev, isLoading: true }));
 setLoadingBalance(true);

 try {
 const chainKey = activeChain.key;
 const result: BalanceResult = await fetchNativeBalance(address, chainKey);

 if (!isMountedRef.current) return;

 if (result.error) {
 setStatus({
 balance: null,
 balanceUsd: null,
 isLoading: false,
 error: result.error,
 lastUpdated: null,
 isStale: true,
 });
 setLoadingBalance(false);
 if (onError) {
 onError(new Error(result.error));
 }
 return;
 }

 let balanceUsd = '0.00';
 try {
 const marketQuote = await getTokenMarketQuote(activeChain.symbol || result.symbol);
 const balanceNum = parseFloat(result.balanceFormatted);
 balanceUsd = (balanceNum * marketQuote.price).toFixed(2);
 } catch {
 balanceUsd = '0.00';
 }

 if (!isMountedRef.current) return;

 const balance = result.balanceFormatted;
 setStatus({
 balance,
 balanceUsd,
 isLoading: false,
 error: null,
 lastUpdated: new Date(result.lastUpdated),
 isStale: result.source === 'fallback',
 });

 setBalance(balance, balanceUsd);
 setLoadingBalance(false);

 if (onBalanceUpdate) {
 onBalanceUpdate(balance, balanceUsd);
 }
 } catch (error) {
 if (!isMountedRef.current) return;

 const errorMessage = error instanceof Error ? error.message : 'Failed to fetch balance';
 setStatus({
 balance: null,
 balanceUsd: null,
 isLoading: false,
 error: errorMessage,
 lastUpdated: null,
 isStale: true,
 });
 setLoadingBalance(false);

 if (onError) {
 onError(error instanceof Error ? error : new Error(errorMessage));
 }
 }
 }, [address, activeChain, setBalance, setLoadingBalance, onBalanceUpdate, onError]);

 const start = useCallback(() => {
 if (isPollingRef.current || !enabled || !address || !activeChain) {
 return;
 }

 isPollingRef.current = true;

 if (initialFetch) {
 fetchBalance();
 }

 intervalIdRef.current = setInterval(fetchBalance, intervalMs);
 }, [enabled, address, activeChain, initialFetch, intervalMs, fetchBalance]);

 const stop = useCallback(() => {
 isPollingRef.current = false;
 if (intervalIdRef.current) {
 clearInterval(intervalIdRef.current);
 intervalIdRef.current = null;
 }
 }, []);

 const refresh = useCallback(async () => {
 await fetchBalance();
 }, [fetchBalance]);

 useEffect(() => {
 if (enabled && address && activeChain) {
 start();
 } else {
 stop();
 }

 return () => {
 stop();
 };
 }, [enabled, address, activeChain, start, stop]);

 return {
 ...status,
 start,
 stop,
 refresh,
 };
}

export default useBalancePolling;

/**
 * useBiometrics — Secure Enclave Biometric Hook
 *
 * SECURITY DESIGN:
 * - `disableDeviceFallback: true` — PIN/passcode bypass is BLOCKED.
 *   Authentication must use the hardware secure enclave (Face ID / fingerprint).
 * - `requireConfirmation: true` — On Android, the user must explicitly tap
 *   "Confirm" after biometric match (prevents accidental or passive auth).
 * - Context-aware prompt strings per operation type so the user knows exactly
 *   what they are authorizing.
 *
 * USAGE:
 *   const { authenticate, biometricLabel, isAvailable } = useBiometrics();
 *   const ok = await authenticate('send_payment');
 */

import * as LocalAuthentication from 'expo-local-authentication';
import { useState, useEffect } from 'react';
import { Platform } from 'react-native';

// ─── Context Types ────────────────────────────────────────────────────────────

/**
 * Each operation that requires biometric auth should pass one of these contexts.
 * This drives context-specific prompt strings shown to the user.
 */
export type BiometricContext =
  | 'send_payment'
  | 'export_key'
  | 'backup_seed'
  | 'app_unlock'
  | 'toggle_biometrics'
  | 'deposit';

const PROMPT_MESSAGES: Record<BiometricContext, string> = {
  send_payment:       'Authorize this transaction with biometrics',
  export_key:         'Authenticate to view your private key',
  backup_seed:        'Authenticate to view your recovery phrase',
  app_unlock:         'Authenticate to access VeilPay',
  toggle_biometrics:  'Confirm your identity to change biometric settings',
  deposit:            'Authenticate to proceed with deposit',
};

// ─── Result Types ─────────────────────────────────────────────────────────────

export interface BiometricAuthResult {
  success: boolean;
  /** True if the user cancelled (vs a hardware/system failure) */
  cancelled: boolean;
  /** True if it's safe to offer a retry (hardware error, not cancelled) */
  retryable: boolean;
  error: string | null;
}

export type BiometricStatus = {
  isAvailable: boolean;
  supportedTypes: LocalAuthentication.AuthenticationType[];
  biometricType: LocalAuthentication.AuthenticationType | null;
  /** Human-readable label derived from the primary biometric type */
  biometricLabel: string;
  isAuthenticated: boolean;
  error: string | null;
};

// ─── Label Resolution ─────────────────────────────────────────────────────────

function resolveBiometricLabel(types: LocalAuthentication.AuthenticationType[]): string {
  const hasFace = types.includes(LocalAuthentication.AuthenticationType.FACIAL_RECOGNITION);
  const hasFingerprint = types.includes(LocalAuthentication.AuthenticationType.FINGERPRINT);
  const hasIris = types.includes(LocalAuthentication.AuthenticationType.IRIS);

  if (Platform.OS === 'ios') {
    if (hasFace) return 'Face ID';
    if (hasFingerprint) return 'Touch ID';
  } else {
    // Android can have multiple
    if (hasFace && hasFingerprint) return 'Biometric Unlock';
    if (hasFingerprint) return 'Fingerprint';
    if (hasFace) return 'Face Unlock';
    if (hasIris) return 'Iris Scan';
  }
  return 'Biometrics';
}

// ─── Hook ─────────────────────────────────────────────────────────────────────

export function useBiometrics() {
  const [status, setStatus] = useState<BiometricStatus>({
    isAvailable: false,
    supportedTypes: [],
    biometricType: null,
    biometricLabel: 'Biometrics',
    isAuthenticated: false,
    error: null,
  });

  useEffect(() => {
    let isMounted = true;

    const checkAvailability = async () => {
      try {
        const [compatible, enrolled, types] = await Promise.all([
          LocalAuthentication.hasHardwareAsync(),
          LocalAuthentication.isEnrolledAsync(),
          LocalAuthentication.supportedAuthenticationTypesAsync(),
        ]);

        if (isMounted) {
          setStatus(prev => ({
            ...prev,
            isAvailable: compatible && enrolled,
            supportedTypes: types,
            biometricType: types[0] ?? null,
            biometricLabel: resolveBiometricLabel(types),
            error: null,
          }));
        }
      } catch {
        if (isMounted) {
          setStatus(prev => ({
            ...prev,
            error: 'Failed to check biometric availability',
          }));
        }
      }
    };
    checkAvailability();
    return () => { isMounted = false; };
  }, []);

  /**
   * Triggers the biometric authentication prompt.
   *
   * @param context - The operation being authorized (drives prompt message).
   *   Defaults to 'app_unlock' if not provided.
   *
   * SECURITY:
   * - `disableDeviceFallback: true` — blocks PIN/passcode fallback.
   *   The secure enclave MUST be used.
   * - `requireConfirmation: true` — Android requires explicit confirmation tap.
   */
  const authenticate = async (context: BiometricContext = 'app_unlock', allowDeviceFallback = false): Promise<BiometricAuthResult> => {
    // If we only allow biometrics but none are available, fail early.
    // If we allow device fallback (PIN/Password), we can proceed even if biometrics aren't enrolled.
    if (!status.isAvailable && !allowDeviceFallback) {
      return {
        success: false,
        cancelled: false,
        retryable: false,
        error: 'Biometric authentication is not available on this device',
      };
    }

    try {
      const result = await LocalAuthentication.authenticateAsync({
        promptMessage: PROMPT_MESSAGES[context],
        fallbackLabel: allowDeviceFallback ? 'Use Passcode' : '',
        cancelLabel: 'Cancel',
        disableDeviceFallback: !allowDeviceFallback,
        requireConfirmation: true,      // SECURITY: Android explicit confirmation
      });

      const success = result.success;

      setStatus(prev => ({
        ...prev,
        isAuthenticated: success,
        error: success ? null : 'Authentication failed',
      }));

      // expo-local-authentication error codes for cancelled actions
      const cancelledError = (result as any).error === 'user_cancel' ||
        (result as any).error === 'system_cancel' ||
        (result as any).error === 'app_cancel';

      return {
        success,
        cancelled: !success && cancelledError,
        retryable: !success && !cancelledError,
        error: success ? null : ((result as any).error ?? 'Authentication failed'),
      };
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Authentication failed';
      setStatus(prev => ({
        ...prev,
        isAuthenticated: false,
        error: message,
      }));
      return {
        success: false,
        cancelled: false,
        retryable: true,
        error: message,
      };
    }
  };

  return {
    ...status,
    authenticate,
  };
}

/**
 * Retry queued commitment saves on app launch.
 *
 * Mounted exactly once at the app root. On mount, it walks the
 * in-memory pending queue (`usePendingCommitmentQueue`) and retries
 * `saveCommitmentRecord` for every entry. Successful retries are
 * dequeued; failed retries stay in the queue, the persistent banner
 * stays visible, and the retry will run again on the next mount.
 *
 * Why "on next launch" maps to "on every mount":
 *
 *   - The pending queue is in-memory only (Requirement 7.6 forbids
 *     persisting `nullifier` / `secret` outside SecureStore, and the
 *     queue exists precisely because SecureStore is misbehaving).
 *   - Therefore any process kill empties the queue. The "retry on
 *     next launch" wording in Requirement 7.7 is best-effort: it
 *     means "before the user can act on the privacy flow again, the
 *     app should re-attempt any pending writes that survived". Mount
 *     is the right hook because it fires on cold launch *and* on
 *     every fresh `App` mount within a session (e.g. after fast
 *     refresh, navigation back to root).
 *
 * The privacy-flow gate (Requirement 7.7 "before the privacy flow
 * becomes available") is enforced by call sites that read
 * `selectHasPendingCommitments` and refuse to start a new max-privacy
 * flow while pending writes exist; this hook only handles the retry
 * itself.
 *
 * See:
 *   - requirements.md Requirement 7.7
 *   - tasks.md task 7.4
 */

import { useEffect } from 'react';

import { saveCommitmentRecord } from '../stores/commitmentStore';
import { usePendingCommitmentQueue } from '../stores/pendingCommitmentQueue';
import { captureMessage } from '../utils/sentry';

export function useDepositPersistenceRecovery(): void {
  useEffect(() => {
    let cancelled = false;

    void (async () => {
      // Snapshot the queue *at mount time*. New entries enqueued
      // mid-flight will be picked up by the next mount; we don't
      // want this loop to retry infinitely against a queue that
      // keeps growing.
      const snapshot = usePendingCommitmentQueue.getState().pending;

      for (const entry of snapshot) {
        if (cancelled) {
          return;
        }

        const { record } = entry;
        usePendingCommitmentQueue.getState().markAttempt(record.commitmentHash);

        try {
          await saveCommitmentRecord(record);
          if (cancelled) {
            return;
          }
          usePendingCommitmentQueue.getState().dequeue(record.commitmentHash);
          captureMessage(
            `[depositPersistence] Recovered queued commitment ${record.commitmentHash.slice(0, 10)}… on launch retry`,
            'info'
          );
        } catch (rawError) {
          // Leave the entry in the queue. The banner stays visible
          // and the next mount will try again. We refresh the
          // entry's `lastError` so the diagnostic message is current.
          const message = rawError instanceof Error
            ? rawError.message
            : typeof rawError === 'string'
              ? rawError
              : 'SecureStore write failed';
          usePendingCommitmentQueue.getState().enqueue(record, new Error(message));
          captureMessage(
            `[depositPersistence] Retry failed for commitment ${record.commitmentHash.slice(0, 10)}…: ${message}`,
            'warning'
          );
        }
      }
    })();

    return () => {
      cancelled = true;
    };
    // Mount-only: we deliberately want this to run once per app
    // mount, not on every queue change. New entries are handled by
    // the next mount.  }, []);
}

import { useCallback, useEffect, useMemo, useState } from 'react';
import {
  createFallbackQuoteMap,
  getTokenMarketData,
  getCachedTokenMarketQuote,
  type MarketQuote,
  type MarketQuoteMap,
} from '../utils/marketData';
import { marketStreamer } from '../utils/marketStreamer';

export interface UseMarketDataResult {
  quotes: MarketQuoteMap;
  isLoading: boolean;
  error: string | null;
  refresh: () => Promise<void>;
  lastUpdated: number | null;
  getQuote: (symbol: string) => MarketQuote;
}

export function useMarketData(
  symbols: readonly string[],
  options: { throttleMs?: number } = {}
): UseMarketDataResult {
  const { throttleMs = 1000 } = options;
  const normalizedSymbols = useMemo(
    () => Array.from(new Set(symbols.map((symbol) => symbol.trim().toUpperCase()).filter(Boolean))).sort(),
    [symbols.join('|')]
  );

  const [quotes, setQuotes] = useState<MarketQuoteMap>(() => createFallbackQuoteMap(normalizedSymbols));
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [lastUpdated, setLastUpdated] = useState<number | null>(null);
  useEffect(() => {
    setQuotes(createFallbackQuoteMap(normalizedSymbols));
    setLastUpdated(null);
  }, [normalizedSymbols.join('|')]);

  const refresh = useCallback(async () => {
    if (normalizedSymbols.length === 0) {
      return;
    }

    setIsLoading(true);
    setError(null);

    try {
      const nextQuotes = await getTokenMarketData(normalizedSymbols);
      setQuotes(nextQuotes);

      const timestamps = Object.values(nextQuotes).map((quote) => quote.lastUpdated);
      const latestTimestamp = timestamps.length > 0 ? Math.max(...timestamps) : null;
      setLastUpdated(latestTimestamp);
    } catch (fetchError) {
      setError(fetchError instanceof Error ? fetchError.message : 'Failed to load market data');
    } finally {
      setIsLoading(false);
    }
  }, [normalizedSymbols]);

  useEffect(() => {
    if (normalizedSymbols.length === 0) {
      return;
    }

    // Bootstrap initial REST fetch
    void refresh();

    // Subscribe to WebSocket streams
    marketStreamer.subscribe(normalizedSymbols);

    // Throttle UI updates to prevent 60fps drops
    const lastUpdateTimes: Record<string, number> = {};

    const handleUpdate = (symbol: string, price: number, change24h: number | null) => {
      if (!normalizedSymbols.includes(symbol)) return;

      const now = Date.now();
      const last = lastUpdateTimes[symbol] || 0;

      if (now - last > throttleMs) {
        lastUpdateTimes[symbol] = now;
        setQuotes(prev => {
          const existing = prev[symbol];
          if (!existing) return prev;

          return {
            ...prev,
            [symbol]: {
              ...existing,
              price,
              change24h,
              lastUpdated: now,
              source: 'binance',
              isStale: false,
            }
          };
        });
      }
    };

    marketStreamer.addListener(handleUpdate);

    return () => {
      marketStreamer.removeListener(handleUpdate);
      marketStreamer.unsubscribe(normalizedSymbols);
    };
  }, [normalizedSymbols, refresh, throttleMs]);

  const getQuote = useCallback(
    (symbol: string) => {
      const normalized = symbol.trim().toUpperCase();
      return quotes[normalized] ?? getCachedTokenMarketQuote(normalized);
    },
    [quotes]
  );

  return {
    quotes,
    isLoading,
    error,
    refresh,
    lastUpdated,
    getQuote,
  };
}

export default useMarketData;

import NetInfo, { NetInfoState } from '@react-native-community/netinfo';
import { useEffect, useState } from 'react';

export type NetworkStatus = {
  isConnected: boolean | null;
  isInternetReachable: boolean | null;
  type: string | null;
};

export function useNetworkStatus(): NetworkStatus {
  const [status, setStatus] = useState<NetworkStatus>({
    isConnected: null,
    isInternetReachable: null,
    type: null,
  });

  useEffect(() => {
    let unsubscribe: (() => void) | null = null;

    try {
      if (typeof NetInfo?.addEventListener !== 'function') {
        throw new Error('NetInfo.addEventListener is unavailable');
      }

      unsubscribe = NetInfo.addEventListener((state: NetInfoState) => {
        setStatus({
          isConnected: state.isConnected,
          isInternetReachable: state.isInternetReachable,
          type: state.type,
        });
      });
    } catch (error) {
      // Some preview runtimes can miss native NetInfo; fail open instead of crashing app boot.
      console.warn('[useNetworkStatus] NetInfo unavailable, skipping network listener.', error);
      setStatus({
        isConnected: true,
        isInternetReachable: null,
        type: null,
      });
    }

    return () => {
      if (unsubscribe) {
        unsubscribe();
      }
    };
  }, []);

  return status;
}

import * as Updates from 'expo-updates';
import { useState, useEffect } from 'react';

export type UpdateStatus = {
  isChecking: boolean;
  isDownloading: boolean;
  isUpdateAvailable: boolean;
  isUpdatePending: boolean;
  error: string | null;
  lastChecked: Date | null;
};

export function useOTAUpdates() {
  const [status, setStatus] = useState<UpdateStatus>({
    isChecking: false,
    isDownloading: false,
    isUpdateAvailable: false,
    isUpdatePending: false,
    error: null,
    lastChecked: null,
  });

  // Only run in production (not in development)
  const isProduction = !__DEV__;

  useEffect(() => {
    if (isProduction) {
      // Check for updates on app start
      checkForUpdate();
    }
  }, [isProduction]);

  const checkForUpdate = async () => {
    if (!isProduction) return;

    setStatus(prev => ({ ...prev, isChecking: true, error: null }));

    try {
      const update = await Updates.checkForUpdateAsync();
      setStatus(prev => ({
        ...prev,
        isChecking: false,
        isUpdateAvailable: update.isAvailable,
        lastChecked: new Date(),
      }));
      return update.isAvailable;
    } catch (error) {
      setStatus(prev => ({
        ...prev,
        isChecking: false,
        error: 'Failed to check for updates',
      }));
      return false;
    }
  };

  const downloadUpdate = async () => {
    if (!isProduction) return false;

    setStatus(prev => ({ ...prev, isDownloading: true, error: null }));

    try {
      const result = await Updates.fetchUpdateAsync();
      setStatus(prev => ({
        ...prev,
        isDownloading: false,
        isUpdatePending: result.isNew,
      }));
      return result.isNew;
    } catch (error) {
      setStatus(prev => ({
        ...prev,
        isDownloading: false,
        error: 'Failed to download update',
      }));
      return false;
    }
  };

  const applyUpdate = async () => {
    if (!isProduction) return;
    await Updates.reloadAsync();
  };

  return {
    ...status,
    isProduction,
    checkForUpdate,
    downloadUpdate,
    applyUpdate,
  };
}

import { useState, useCallback } from 'react';
import { useWalletStore } from '../stores/walletStore';
import { useTransactionStore } from '../stores/transactionStore';
import { getOnrampConfig } from '../utils/onramp';
import { captureError } from '../utils/sentry';
import type { FiatGatewayProvider } from '../utils/fiatGateway';

const BACKEND_URL = process.env.EXPO_PUBLIC_BACKEND_BASE_URL;

export interface OnrampQuoteRequest {
  fiatAmount?: string;
  fiatCurrency?: string;
  cryptoToken: string;
  chainKey: string;
  flow: 'buy' | 'sell';
}

export interface OnrampSession {
  url: string;
  orderId: string;
}

export const useOnramp = () => {
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const { address } = useWalletStore();
  const setLatestOnrampOrder = useTransactionStore(s => s.setLatestOnrampOrder);

  /**
   * Fetches a signed Onramp URL from the VeilPay backend.
   */
  const getOnrampUrl = useCallback(async (params: OnrampQuoteRequest): Promise<OnrampSession | null> => {
    if (!address) {
      setError('Wallet not connected');
      return null;
    }

    if (!BACKEND_URL) {
      setError('Backend configuration missing');
      return null;
    }

    setIsLoading(true);
    setError(null);

    try {
      const config = getOnrampConfig(params.cryptoToken, params.chainKey);
      
      const response = await fetch(`${BACKEND_URL}/api/v1/onramp/url`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          userAddress: address,
          fiatAmount: params.fiatAmount,
          fiatCurrency: params.fiatCurrency || 'INR',
          cryptoToken: config.coinCode,
          chainKey: params.chainKey,
          flow: params.flow,
        }),
      });

      if (!response.ok) {
        throw new Error('Failed to fetch Onramp URL');
      }

      const data = await response.json();
      const orderId = typeof data.orderId === 'string' ? data.orderId : '';

      if (!orderId) {
        throw new Error('Failed to create Onramp order');
      }

      // Track the order in local state
      setLatestOnrampOrder({
        provider: 'onramp_money' as FiatGatewayProvider,
        id: orderId,
        orderId,
        walletAddress: address,
        userAddress: address,
        flow: params.flow,
        status: 'pending',
        fiatAmount: params.fiatAmount || '0',
        fiatCurrency: params.fiatCurrency || 'INR',
        cryptoToken: params.cryptoToken,
        chainKey: params.chainKey,
        updatedAt: Date.now(),
      });

      return {
        url: data.url as string,
        orderId,
      };
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Unknown error';
      setError(message);
      captureError(err instanceof Error ? err : new Error(message));
      return null;
    } finally {
      setIsLoading(false);
    }
  }, [address, setLatestOnrampOrder]);

  /**
   * Polls the backend for the status of a specific order.
   */
  const checkOrderStatus = useCallback(async (internalOrderId: string) => {
    if (!BACKEND_URL) return null;

    try {
      const response = await fetch(`${BACKEND_URL}/api/v1/onramp/status/${internalOrderId}`);
      if (!response.ok) return null;
      
      const order = await response.json();
      const normalizedOrderId = typeof order.orderId === 'string' && order.orderId.length > 0 ? order.orderId : internalOrderId;
      
      // Sync local state if changed
      setLatestOnrampOrder({
        ...order,
        provider: 'onramp_money',
        id: order.id ?? normalizedOrderId,
        orderId: normalizedOrderId,
        walletAddress: order.walletAddress ?? order.userAddress,
        updatedAt: Date.now(),
      });

      return order;
    } catch (err) {
      return null;
    }
  }, [setLatestOnrampOrder]);

  return {
    getOnrampUrl,
    checkOrderStatus,
    isLoading,
    error,
  };
};

// Public inputs: [merkleRoot, nullifierHash, recipient, amount] — see design.md §Public input ordering contract
//
// usePaymentTransaction — single-source dispatcher for the three privacy levels.
// =============================================================================
//
// This hook is the seam where the UI's chosen `privacyLevel` is turned into
// concrete on-chain action. The shape is deliberate: a *single*
// `switch (privacyLevel)` dispatcher lives inside `handleConfirmSend`, so the
// `'standard'` / `'stealth'` / `'max'` paths cannot accidentally bleed into
// each other (e.g. `'max'` can never call `StealthAnnouncer`, `'standard'`
// can never enter the pool). See design.md §`apps/consumer-app/src/hooks/
// usePaymentTransaction.ts` and Requirements 4.1, 4.2, 4.6, 4.7, 4.8, 7.3,
// 7.4, 8.1, 8.3, 8.4, 12.4, 12.5.
//
// Privacy branches:
//
//   `'standard'`  → existing direct token transfer (EVM / SVM / MVM / XLM).
//                   Never touches `StealthAnnouncer`, never enters the pool.
//
//   `'stealth'`   → derive a one-time stealth address with the dual-key
//                   `stealthEngine`, fund it with a regular EVM transfer,
//                   wait for on-chain confirmation, then call
//                   `StealthAnnouncer.announce(1, stealthAddress,
//                   ephemeralPubKey, '0x')`. Per Requirement 4.6 the announce
//                   call MUST happen before the UI surface flips to
//                   `'confirmed'`. On announce failure we surface a warning
//                   toast but keep the underlying transfer marked successful
//                   — the funds did move, only the discovery hint failed.
//
//   `'max'`       → load the source `CommitmentRecord` from SecureStore (or
//                   guide the user back to deposit if missing), run
//                   `ZkpProver` to generate a Groth16 proof against the
//                   pool's current Merkle root, post the result to the
//                   relayer, poll for on-chain confirmation, and on success
//                   `markSpent` the record so it is never reused.
//
// Pre-flight guard: when `privacyLevel ∈ {stealth, max}` and the privacy
// stack is not configured (`deployments/sepolia.json` still holds zero
// addresses), we bail with a config-error toast rather than silently
// transacting against the zero address. Requirements 13.2, 13.3.
//
// Implementation notes / TODOs:
//   * `'stealth'` reads only one key from the directory today — the
//     consumer-app `directory.fetchRecipientPublicKey` returns a single
//     viewing-key hex. The new dual-key engine wants both viewing pub *and*
//     spending pub. As an interim bridge we feed the same key into both
//     slots and flag this with a TODO so the directory extension to a
//     dual-key meta-address (out of scope for task 9.2) lands in one place.
//   * `'max'` requires `pathElements`, `pathIndices`, and `nullifierHash`
//     to feed the prover. `CommitmentRecord` does not yet carry the path
//     data nor a precomputed `nullifierHash`. Until task 11.x lands the
//     deposit-time path-stash and the on-chain reconstruction fallback,
//     `'max'` throws a clear "not yet implemented" error after loading
//     the record. The dispatcher *shape* is what task 9.2 establishes —
//     the missing inputs surface as a typed error rather than as a silent
//     failure or as a placeholder proof submission.
import 'react-native-get-random-values';
import { useState, useEffect, useRef } from 'react';
import { ethers } from 'ethers';
import { parseEther } from 'viem';
import { Buffer } from 'buffer';
import { LAMPORTS_PER_SOL } from '@solana/web3.js';

import { useWalletStore } from '../stores/walletStore';
import { useNetworkStatus } from '../hooks/useNetworkStatus';
import { useToast } from '../components/Toast';
import {
  signAndSendTransaction,
  deriveAddressFromStoredMnemonic,
} from '../utils/secureSigner';
import { signAndSendSolanaTransaction } from '../utils/solanaSigner';
import { signAndSendAptosTransaction } from '../utils/aptosSigner';
import { signAndSendStellarTransaction } from '../utils/stellarSigner';
import {
  TransactionError,
  TransactionResult,
  getStoredMnemonic,
} from '../utils/transactions';
import { getRpcUrl } from '../utils/rpc';
import { encryptNote, generateEphemeralKeyPair } from '../utils/encryption';
import { deriveStealthAddress } from '../utils/stealthEngine';
import { fetchRecipientPublicKey } from '../utils/directory';
import { pollTransactionStatus } from '../utils/txStatusPoller';
import {
  estimateTransactionGas,
  isGasExpensive,
  type GasEstimate,
} from '../utils/gasEstimator';
import {
  loadCommitmentRecord,
  markSpent,
  type Hex,
} from '../stores/commitmentStore';
import { submitWithdraw, RelayerError } from '../services/relayerClient';
import type { WithdrawRequest } from '../schemas/withdrawRequest';
import {
  isPrivacyStackConfigured,
  STEALTH_ANNOUNCER_ADDRESS,
  VEIL_POOL_ADDRESS,
} from '../constants/contracts';
import { trackEvent } from '../utils/analytics';
import { ANALYTICS_EVENTS } from '../utils/analyticsEvents';
import type { PrivacyLevel } from '../stores/settingsStore';
import type { ZkpProverRef } from '../components/ZkpProver';
import type { UiTxStatus } from '../components/payment/TransactionStatusCard';

// ABI fragment for the single `StealthAnnouncer.announce` call we make on
// the stealth path. Kept inline rather than importing the full contract
// JSON so the bundle stays small — the hook only ever needs this one
// function selector.
const ANNOUNCER_ABI = [
  'function announce(uint256 schemeId, address stealthAddress, bytes ephemeralPubKey, bytes metadata) external',
] as const;

interface PaymentTransactionParams {
  recipient: string;
  amount: string;
  memo: string;
  token: string;
  tokenAddress?: string;
  tokenDecimals?: number;
  /**
   * Selected privacy level. Narrowed to the canonical union so callers
   * can no longer pass arbitrary strings — the dispatcher's `default`
   * branch surfaces any drift as a runtime error in development.
   */
  privacyLevel: PrivacyLevel;
  ethPrice: number | null;
  activeNetworkKey: string;
  selectedNetwork: any;
  isSendSupported: boolean;
  zkpProverRef: React.RefObject<ZkpProverRef | null>;
  /**
   * Required for `privacyLevel === 'max'`: identifies the source
   * `CommitmentRecord` in SecureStore that the withdraw will spend.
   * Ignored on `'standard'` and `'stealth'`. When missing on `'max'`
   * the dispatcher emits a "deposit first" guidance toast.
   */
  sourceCommitmentHash?: Hex;
}

export function usePaymentTransaction({
  recipient,
  amount,
  memo,
  token,
  tokenAddress,
  tokenDecimals,
  privacyLevel,
  ethPrice,
  activeNetworkKey,
  selectedNetwork,
  isSendSupported,
  zkpProverRef,
  sourceCommitmentHash,
}: PaymentTransactionParams) {
  const [txStatus, setTxStatus] = useState<UiTxStatus>('idle');
  const [txResult, setTxResult] = useState<TransactionResult | null>(null);
  const [gasEstimate, setGasEstimate] = useState<GasEstimate | null>(null);
  const [gasExpensive, setGasExpensive] = useState(false);
  const [hasMnemonic, setHasMnemonic] = useState<boolean | null>(null);

  const isMountedRef = useRef(true);
  const pollAbortRef = useRef<AbortController | null>(null);

  const { activeChain, address } = useWalletStore();
  const { isConnected } = useNetworkStatus();
  const toast = useToast();

  const isWalletVerificationPending = hasMnemonic === null;
  const isSendDisabled =
    isWalletVerificationPending || hasMnemonic === false || !isSendSupported;

  useEffect(() => {
    async function checkMnemonic() {
      const addr = await deriveAddressFromStoredMnemonic();
      if (isMountedRef.current) {
        setHasMnemonic(addr !== null);
      }
    }
    checkMnemonic();
  }, []);

  useEffect(() => {
    isMountedRef.current = true;
    return () => {
      isMountedRef.current = false;
      pollAbortRef.current?.abort();
    };
  }, []);
  useEffect(() => {
    if (txStatus !== 'idle') {
      return;
    }
    if (!recipient || !amount || !address || !isSendSupported) {
      setGasEstimate(null);
      setGasExpensive(false);
      return;
    }

    let isCancelled = false;

    const refreshGasEstimate = async () => {
      try {
        const parsedAmount = Number.parseFloat(amount);

        if (!Number.isFinite(parsedAmount) || parsedAmount <= 0) {
          setGasEstimate(null);
          setGasExpensive(false);
          return;
        }

        let estimate;
        if (activeChain?.type === 'svm') {
          const estimatedCostWei = 5000n;
          const estimatedCostEth = (
            Number(estimatedCostWei) / LAMPORTS_PER_SOL
          ).toString();
          estimate = {
            gasLimit: 0n,
            maxFeePerGas: 0n,
            maxPriorityFeePerGas: 0n,
            gasPrice: 0n,
            estimatedCostWei,
            estimatedCostEth,
            estimatedCostUsd: null,
            isStale: false,
            fetchedAt: Date.now(),
          } as GasEstimate;
        } else if (activeChain?.type === 'mvm') {
          const estimatedCostWei = 200000n;
          const estimatedCostEth = '0.0002';
          estimate = {
            gasLimit: 2000n,
            maxFeePerGas: 100n,
            maxPriorityFeePerGas: 0n,
            gasPrice: 100n,
            estimatedCostWei,
            estimatedCostEth,
            estimatedCostUsd: null,
            isStale: false,
            fetchedAt: Date.now(),
          } as GasEstimate;
        } else if (activeChain?.type === 'xlm') {
          // Stellar base fee: 100 stroops = 0.00001 XLM
          const estimatedCostWei = 100n;
          const estimatedCostEth = '0.00001';
          estimate = {
            gasLimit: 0n,
            maxFeePerGas: 0n,
            maxPriorityFeePerGas: 0n,
            gasPrice: 0n,
            estimatedCostWei,
            estimatedCostEth,
            estimatedCostUsd: null,
            isStale: false,
            fetchedAt: Date.now(),
          } as GasEstimate;
        } else {
          estimate = await estimateTransactionGas(
            {
              to: recipient,
              value: parseEther(parsedAmount.toString()),
              from: address,
            },
            activeNetworkKey,
            ethPrice ?? undefined
          );
        }

        if (isCancelled || !isMountedRef.current) {
          return;
        }

        setGasEstimate(estimate);
        setGasExpensive(isGasExpensive(estimate));
      } catch {
        if (isCancelled || !isMountedRef.current) {
          return;
        }
        setGasEstimate(null);
        setGasExpensive(false);
      }
    };

    refreshGasEstimate();
    const intervalId = setInterval(refreshGasEstimate, 15000);

    return () => {
      isCancelled = true;
      clearInterval(intervalId);
    };
  }, [
    activeNetworkKey,
    address,
    amount,
    ethPrice,
    isSendSupported,
    recipient,
    txStatus,
    activeChain,
  ]);

  const handleConfirmSend = async () => {
    const attemptStartedAt = Date.now();

    // -----------------------------------------------------------------
    // Pre-flight validation — same checks as before, ordered top-down.
    // -----------------------------------------------------------------
    if (!recipient || !amount) {
      trackEvent(ANALYTICS_EVENTS.PAYMENT_SEND_VALIDATION_FAILED, {
        reason: 'missing_payment_details',
      });
      toast.show('Missing payment details', 'error');
      return;
    }

    const parsedAmount = Number.parseFloat(amount);
    if (!Number.isFinite(parsedAmount) || parsedAmount <= 0) {
      trackEvent(ANALYTICS_EVENTS.PAYMENT_SEND_VALIDATION_FAILED, {
        reason: 'invalid_amount',
      });
      toast.show('Invalid payment amount', 'error');
      return;
    }

    if (isWalletVerificationPending) {
      trackEvent(ANALYTICS_EVENTS.PAYMENT_SEND_VALIDATION_FAILED, {
        reason: 'wallet_verification_pending',
      });
      toast.show('Wallet verification in progress. Please wait.', 'info');
      return;
    }

    if (hasMnemonic === false) {
      trackEvent(ANALYTICS_EVENTS.PAYMENT_SEND_VALIDATION_FAILED, {
        reason: 'wallet_not_initialized',
      });
      toast.show(
        'Wallet not properly initialized. Please re-import your wallet.',
        'error'
      );
      return;
    }

    if (!isSendSupported) {
      trackEvent(ANALYTICS_EVENTS.PAYMENT_SEND_VALIDATION_FAILED, {
        reason: 'unsupported_network',
      });
      toast.show(
        'Payments are only supported on EVM networks in this build.',
        'error'
      );
      return;
    }

    if (isConnected === false) {
      trackEvent(ANALYTICS_EVENTS.PAYMENT_SEND_VALIDATION_FAILED, {
        reason: 'offline',
      });
      toast.show('No internet connection', 'error');
      return;
    }

    // Privacy-stack fail-fast: if the user picked a privacy-stack-backed
    // level but the build does not have valid contract addresses, bail
    // before any signing happens. We surface `'failed'` in the UI so the
    // user is not stuck with a spinner; the toast carries the reason.
    if (
      (privacyLevel === 'stealth' || privacyLevel === 'max') &&
      !isPrivacyStackConfigured()
    ) {
      trackEvent(ANALYTICS_EVENTS.PAYMENT_SEND_VALIDATION_FAILED, {
        reason: 'privacy_stack_not_configured',
        privacy_level: privacyLevel,
      });
      toast.show('Privacy stack not configured for this build.', 'error');
      setTxStatus('failed');
      return;
    }

    trackEvent(ANALYTICS_EVENTS.PAYMENT_SEND_ATTEMPTED, {
      network_key: activeNetworkKey,
      token,
      privacy_level: privacyLevel,
      has_memo: Boolean(memo),
    });

    setTxResult(null);

    try {
      // -------------------------------------------------------------
      // Single dispatcher — the load-bearing shape for task 9.2.
      // -------------------------------------------------------------
      switch (privacyLevel) {
        case 'standard': {
          await runStandardFlow();
          break;
        }
        case 'stealth': {
          await runStealthFlow();
          break;
        }
        case 'max': {
          await runMaxFlow();
          break;
        }
        default: {
          // Exhaustiveness — `privacyLevel` is narrowed to the canonical
          // union, so this is unreachable in well-typed code. We leave
          // the throw for runtime defence in case a JS caller bypasses
          // TypeScript and feeds a stale value.
          const exhaustive: never = privacyLevel;
          throw new Error(`Unknown privacy level: ${String(exhaustive)}`);
        }
      }
    } catch (error) {
      if (!isMountedRef.current) {
        return;
      }

      setTxStatus('failed');

      if (error instanceof TransactionError) {
        trackEvent(ANALYTICS_EVENTS.PAYMENT_SEND_FAILED, {
          network_key: activeNetworkKey,
          reason: error.code,
          message: error.message,
          confirmation_time_ms: Date.now() - attemptStartedAt,
        });

        switch (error.code) {
          case 'INSUFFICIENT_FUNDS':
            toast.show(
              'Insufficient funds. Please add more ETH to your wallet.',
              'error'
            );
            break;
          case 'INVALID_ADDRESS':
            toast.show(
              'Invalid recipient address. Please check and try again.',
              'error'
            );
            break;
          case 'NETWORK_ERROR':
            toast.show(
              'Network error. Please check your connection and try again.',
              'error'
            );
            break;
          case 'USER_REJECTED':
            toast.show('Transaction cancelled.', 'error');
            break;
          default:
            toast.show(error.message, 'error');
        }
      } else if (error instanceof RelayerError) {
        trackEvent(ANALYTICS_EVENTS.PAYMENT_SEND_FAILED, {
          network_key: activeNetworkKey,
          reason: `relayer_${error.kind}`,
          message: error.message,
          status: error.status,
          confirmation_time_ms: Date.now() - attemptStartedAt,
        });
        const statusSuffix =
          typeof error.status === 'number' ? ` (HTTP ${error.status})` : '';
        toast.show(`Relayer error: ${error.message}${statusSuffix}`, 'error');
      } else {
        const errorMessage =
          error instanceof Error ? error.message : 'Failed to send payment';
        trackEvent(ANALYTICS_EVENTS.PAYMENT_SEND_FAILED, {
          network_key: activeNetworkKey,
          reason: 'unknown',
          message: errorMessage,
          confirmation_time_ms: Date.now() - attemptStartedAt,
        });
        toast.show(errorMessage, 'error');
      }
    }

    // ===================================================================
    // Per-branch flow helpers
    // ===================================================================

    /**
     * `'standard'` flow — direct token transfer on the active chain.
     * Never calls the announcer or the pool. Memo encryption (when a memo
     * is present and the recipient is in the directory) is preserved
     * here because it is orthogonal to the privacy stack.
     */
    async function runStandardFlow(): Promise<void> {
      const chainType = activeChain?.type ?? 'evm';
      let encryptedPayload: any = undefined;

      if (memo) {
        const recipientPubKeyHex = await fetchRecipientPublicKey(
          recipient,
          chainType
        );
        if (recipientPubKeyHex) {
          const hexStr = recipientPubKeyHex.startsWith('0x')
            ? recipientPubKeyHex.slice(2)
            : recipientPubKeyHex;
          const recipientPubKeyBytes = new Uint8Array(
            hexStr.match(/.{1,2}/g)?.map((byte) => parseInt(byte, 16)) || []
          );
          const senderKeys = generateEphemeralKeyPair();
          encryptedPayload = encryptNote(
            memo,
            recipientPubKeyBytes,
            senderKeys.secretKey
          );
        }
        // If the recipient has no directory entry we silently drop the
        // memo on the standard path — the user already accepted the
        // standard privacy level which makes plaintext the only
        // alternative, and we'd rather lose the memo than reveal it.
      }

      setTxStatus('sending');

      let result;
      if (activeChain?.type === 'svm') {
        result = await signAndSendSolanaTransaction(
          {
            to: recipient,
            value: parsedAmount.toString(),
            tokenAddress,
            tokenDecimals,
          },
          activeNetworkKey,
          undefined
        );
      } else if (activeChain?.type === 'mvm') {
        result = await signAndSendAptosTransaction(
          { to: recipient, value: parsedAmount.toString() },
          activeNetworkKey,
          undefined
        );
      } else if (activeChain?.type === 'xlm') {
        result = await signAndSendStellarTransaction(
          {
            to: recipient,
            value: parsedAmount.toString(),
            // Stellar only supports short text memos.
            data: memo ? memo.slice(0, 28) : undefined,
          },
          activeNetworkKey,
          undefined
        );
      } else {
        result = await signAndSendTransaction(
          {
            to: recipient,
            value: parsedAmount.toString(),
            data: encryptedPayload
              ? `0x${Buffer.from(JSON.stringify(encryptedPayload)).toString('hex')}`
              : undefined,
          },
          activeNetworkKey,
          ethPrice ?? undefined
        );
      }

      setGasExpensive(isGasExpensive(result.gasEstimate));
      await pollAndApply(result.hash, /* finalizeOnConfirm */ undefined);
    }

    /**
     * `'stealth'` flow — derive a one-time stealth address with the dual-key
     * engine, fund it, wait for confirmation, then announce. Per
     * Requirement 4.6 the announce call MUST happen before we flip the
     * UI surface to `'confirmed'`.
     *
     * Stealth path is EVM-only: the announcer contract is on Sepolia and
     * the dual-key engine emits SEC1-compressed pubkeys keyed off
     * secp256k1. SVM/MVM/XLM are rejected upstream by the privacy-level
     * UI, but we double-check here.
     */
    async function runStealthFlow(): Promise<void> {
      const chainType = activeChain?.type ?? 'evm';
      if (chainType !== 'evm') {
        throw new Error(
          'Stealth privacy is only supported on EVM networks in this build.'
        );
      }

      setTxStatus('stealth_deriving');

      // TODO(directory): the directory currently exposes a single viewing
      // key per merchant. The dual-key stealth engine wants both viewing
      // *and* spending public keys. Until the directory is extended to
      // serve a meta-address, we feed the same key into both slots so
      // the engine still produces a derivable address. The recipient's
      // scanner will recover correctly only after the directory upgrade.
      const recipientPubKey = await fetchRecipientPublicKey(
        recipient,
        chainType
      );
      if (!recipientPubKey) {
        throw new Error(
          'Recipient public key not found in directory for stealth addressing'
        );
      }
      const recipientHex = (recipientPubKey.startsWith('0x')
        ? recipientPubKey
        : `0x${recipientPubKey}`) as Hex;

      const { stealthAddress, ephemeralPubKey } = deriveStealthAddress(
        recipientHex,
        recipientHex
      );

      // Fund the stealth address with a regular EVM transfer. We never
      // attach the ephemeral key as calldata on the stealth path — the
      // announcer is the canonical discovery channel.
      setTxStatus('sending');
      const result = await signAndSendTransaction(
        {
          to: stealthAddress,
          value: parsedAmount.toString(),
        },
        activeNetworkKey,
        ethPrice ?? undefined
      );
      setGasExpensive(isGasExpensive(result.gasEstimate));

      setTxResult({ hash: result.hash, status: 'pending' });
      setTxStatus('pending');
      toast.show(
        'Transaction submitted! Waiting for confirmation...',
        'success'
      );

      const pollResult = await pollTransactionStatus({
        chainKey: activeNetworkKey,
        txHash: result.hash,
        fromAddress: address || '',
        toAddress: stealthAddress,
        amountEth: parsedAmount.toString(),
        tokenSymbol: token || 'ETH',
        networkName: selectedNetwork?.name || activeNetworkKey,
        // The on-chain record is still a "standard"-shaped transfer; the
        // stealth nature is a function of the announcer event, which the
        // recipient scanner correlates separately.
        privacyLevel: 'standard',
        signal: pollAbortRef.current?.signal,
      });

      if (!isMountedRef.current) {
        return;
      }

      if (pollResult.status !== 'completed') {
        // Fund transfer didn't confirm within the poll window — fall back
        // to the same UX the standard path uses for non-confirmed
        // outcomes. We do NOT announce in this case: announcing for an
        // unconfirmed transfer would publish a stealth address that may
        // never receive funds.
        applyNonConfirmedOutcome(result.hash, pollResult.status);
        return;
      }

      // The fund transfer is confirmed on-chain. Announce BEFORE we
      // surface `'confirmed'` to the UI (Requirement 4.6). On announce
      // failure the underlying transfer is still successful — we surface
      // a warning toast and keep the UI on the success path.
      try {
        const mnemonicWords = await getStoredMnemonic();
        if (!mnemonicWords || mnemonicWords.length === 0) {
          throw new Error('No wallet mnemonic available for announce signer');
        }
        const rpcUrl = getRpcUrl(activeNetworkKey);
        if (!rpcUrl) {
          throw new Error(`No RPC URL for chain ${activeNetworkKey}`);
        }
        const provider = new ethers.JsonRpcProvider(rpcUrl);
        const signer = ethers.Wallet.fromPhrase(
          mnemonicWords.join(' '),
          provider
        );
        const announcer = new ethers.Contract(
          STEALTH_ANNOUNCER_ADDRESS,
          ANNOUNCER_ABI,
          signer
        );
        // schemeId = 1 is the secp256k1 ERC-5564 scheme implemented by
        // the indexer's stealth scanner. metadata = '0x' until the wire
        // format adds optional view tags or per-token hints.
        const announceTx = await announcer.announce(
          1,
          stealthAddress,
          ephemeralPubKey,
          '0x'
        );
        await announceTx.wait();
        trackEvent(ANALYTICS_EVENTS.PAYMENT_SEND_SUBMITTED, {
          network_key: activeNetworkKey,
          tx_hash: result.hash,
          announce_tx_hash: announceTx.hash,
          privacy_level: 'stealth',
        });
      } catch (announceErr) {
        const message =
          announceErr instanceof Error ? announceErr.message : String(announceErr);
        // Underlying transfer succeeded — keep the UI on the success
        // path and warn the user that the discovery hint failed. A
        // re-run of the announce step is a follow-up integration concern.
        trackEvent(ANALYTICS_EVENTS.PAYMENT_SEND_FAILED, {
          network_key: activeNetworkKey,
          tx_hash: result.hash,
          reason: 'stealth_announce_failed',
          message,
          confirmation_time_ms: Date.now() - attemptStartedAt,
        });
        toast.show(
          'Stealth announcement failed; payment was still sent.',
          'warning'
        );
      }

      // Now flip the UI to confirmed (announce attempted, transfer
      // confirmed regardless of announce outcome).
      const finalTxResult: TransactionResult = {
        hash: result.hash,
        status: 'confirmed',
      };
      setTxResult(finalTxResult);
      setTxStatus('confirmed');
      trackEvent(ANALYTICS_EVENTS.PAYMENT_SEND_CONFIRMED, {
        network_key: activeNetworkKey,
        tx_hash: result.hash,
        confirmation_time_ms: Date.now() - attemptStartedAt,
        privacy_level: 'stealth',
      });
      toast.show('Payment sent successfully!', 'success');
    }

    /**
     * `'max'` flow — load the source `CommitmentRecord`, prove against
     * the pool's current Merkle root, and dispatch to the relayer.
     *
     * NOTE: the deposit-time Merkle path (`pathElements`, `pathIndices`)
     * is not yet stored alongside the `CommitmentRecord`, and the
     * consumer-app does not yet ship a Poseidon hash for the
     * `nullifierHash = Poseidon(nullifier)` step. The dispatcher *shape*
     * is the deliverable for task 9.2; the missing inputs surface as a
     * typed "not yet implemented" error so task 11.x can wire them in
     * without touching the dispatcher again.
     */
    async function runMaxFlow(): Promise<void> {
      if (!sourceCommitmentHash) {
        toast.show(
          'No commitment record selected. Deposit first to use max privacy.',
          'error'
        );
        setTxStatus('failed');
        return;
      }

      const record = await loadCommitmentRecord(sourceCommitmentHash);
      if (!record) {
        toast.show(
          'No commitment record found. Deposit first to use max privacy.',
          'error'
        );
        setTxStatus('failed');
        return;
      }
      if (record.spent) {
        toast.show(
          'This commitment has already been spent. Pick a fresh deposit.',
          'error'
        );
        setTxStatus('failed');
        return;
      }

      setTxStatus('proving');

      // TODO(scanning): reconstruct the Merkle path
      // (`pathElements`, `pathIndices`) from chain — either by extending
      // `CommitmentRecord` to stash the deposit-time path or by reading
      // the leaf set via an indexer call. Same for `nullifierHash`,
      // which needs Poseidon(record.nullifier). These are tracked in
      // tasks 11.x. Until then we throw a clear "not yet implemented"
      // error so the dispatcher's shape is what task 9.2 ships and the
      // missing pieces are visible to integration.
      const recordWithPath = record as typeof record & {
        pathElements?: Hex[];
        pathIndices?: number[];
        nullifierHash?: Hex;
      };
      if (
        !recordWithPath.pathElements ||
        !recordWithPath.pathIndices ||
        !recordWithPath.nullifierHash
      ) {
        throw new Error(
          'not yet implemented: Merkle path and nullifierHash for max-privacy withdraw are not yet wired to CommitmentRecord (tracked in tasks 11.x)'
        );
      }

      const proofResult = await zkpProverRef.current?.generateProof({
        nullifier: record.nullifier,
        secret: record.secret,
        pathElements: recordWithPath.pathElements,
        pathIndices: recordWithPath.pathIndices,
        merkleRoot: record.merkleRoot,
        nullifierHash: recordWithPath.nullifierHash,
        recipient,
        amount: parsedAmount.toString(),
      });
      if (!proofResult) {
        throw new Error('ZkpProver returned no proof');
      }
      toast.show('ZK Proof generated successfully!', 'success');

      setTxStatus('relaying');

      const requestBody: WithdrawRequest = {
        nullifierHash: recordWithPath.nullifierHash,
        proof: proofResult.proof as `0x${string}`,
        publicSignals: proofResult.publicSignals as `0x${string}`[],
        merkleRoot: record.merkleRoot,
        recipient: recipient as `0x${string}`,
        token: record.token,
        amount: record.amount,
        chainKey: 'evm-sepolia',
        contractAddress: VEIL_POOL_ADDRESS as `0x${string}`,
      };

      const { txHash } = await submitWithdraw(requestBody);

      setTxResult({ hash: txHash, status: 'pending' });
      setTxStatus('pending');
      toast.show(
        'Withdraw submitted via relayer! Waiting for confirmation...',
        'success'
      );

      const pollResult = await pollTransactionStatus({
        chainKey: activeNetworkKey,
        txHash,
        fromAddress: address || '',
        toAddress: recipient,
        amountEth: parsedAmount.toString(),
        tokenSymbol: token || 'ETH',
        networkName: selectedNetwork?.name || activeNetworkKey,
        privacyLevel: 'max',
        signal: pollAbortRef.current?.signal,
      });

      if (!isMountedRef.current) {
        return;
      }

      if (pollResult.status === 'completed') {
        // Mark the record spent so it cannot be reused. SecureStore
        // failure here is logged but does not flip the UI to failed —
        // the on-chain nullifier-spent flag is the authoritative double-
        // spend guard, and the local record is a UX optimization.
        try {
          await markSpent(sourceCommitmentHash);
        } catch (markErr) {
          const message =
            markErr instanceof Error ? markErr.message : String(markErr);
          console.warn('[usePaymentTransaction] markSpent failed', message);
        }

        setTxResult({ hash: txHash, status: 'confirmed' });
        setTxStatus('confirmed');
        trackEvent(ANALYTICS_EVENTS.PAYMENT_SEND_CONFIRMED, {
          network_key: activeNetworkKey,
          tx_hash: txHash,
          confirmation_time_ms: Date.now() - attemptStartedAt,
          privacy_level: 'max',
        });
        toast.show('Payment sent successfully!', 'success');
        return;
      }

      applyNonConfirmedOutcome(txHash, pollResult.status);
    }

    // ===================================================================
    // Shared post-broadcast helpers
    // ===================================================================

    /**
     * Standard polling step shared by the `'standard'` flow. Updates the
     * UI to `'pending'`, polls, then maps the final poller status into
     * the appropriate UI state and analytics event.
     */
    async function pollAndApply(
      hash: string,
      _finalizeOnConfirm: undefined
    ): Promise<void> {
      setTxResult({ hash, status: 'pending' });
      setTxStatus('pending');
      toast.show(
        'Transaction submitted! Waiting for confirmation...',
        'success'
      );

      const pollResult = await pollTransactionStatus({
        chainKey: activeNetworkKey,
        txHash: hash,
        fromAddress: address || '',
        toAddress: recipient,
        amountEth: parsedAmount.toString(),
        tokenSymbol: token || 'ETH',
        networkName: selectedNetwork?.name || activeNetworkKey,
        privacyLevel: 'standard',
        signal: pollAbortRef.current?.signal,
      });

      if (!isMountedRef.current) {
        return;
      }

      if (pollResult.status === 'completed') {
        setTxResult({ hash, status: 'confirmed' });
        setTxStatus('confirmed');
        trackEvent(ANALYTICS_EVENTS.PAYMENT_SEND_CONFIRMED, {
          network_key: activeNetworkKey,
          tx_hash: hash,
          confirmation_time_ms: Date.now() - attemptStartedAt,
        });
        toast.show('Payment sent successfully!', 'success');
        return;
      }

      applyNonConfirmedOutcome(hash, pollResult.status);
    }

    /**
     * Shared mapping for `'failed'` and `'pending'` (timeout) outcomes —
     * keeps analytics and toasts consistent across the standard, stealth,
     * and max paths.
     */
    function applyNonConfirmedOutcome(
      hash: string,
      status: 'failed' | 'pending' | 'completed'
    ): void {
      if (status === 'failed') {
        setTxResult({ hash, status: 'failed' });
        setTxStatus('failed');
        trackEvent(ANALYTICS_EVENTS.PAYMENT_SEND_FAILED, {
          network_key: activeNetworkKey,
          tx_hash: hash,
          reason: 'on_chain_failure',
          confirmation_time_ms: Date.now() - attemptStartedAt,
        });
        toast.show('Transaction failed on-chain.', 'error');
        return;
      }
      // 'pending' — poller timed out; we keep the record but surface the
      // delay so the user knows to check history later.
      setTxResult({ hash, status: 'pending' });
      setTxStatus('pending');
      trackEvent(ANALYTICS_EVENTS.PAYMENT_SEND_FAILED, {
        network_key: activeNetworkKey,
        tx_hash: hash,
        reason: 'confirmation_timeout',
        confirmation_time_ms: Date.now() - attemptStartedAt,
      });
      toast.show(
        'Transaction submitted but confirmation is taking longer than expected. Check your history later.',
        'info'
      );
    }
  };

  return {
    txStatus,
    txResult,
    gasEstimate,
    gasExpensive,
    isWalletVerificationPending,
    isSendDisabled,
    handleConfirmSend,
  };
}

