  }, [    address,
    authenticate,
    biometricsEnabled,
    isAvailable,
    navigation,
    parsedAmount,
    selectedCrypto,
    selectedCurrency,
    selectedPaymentMethod,
    toast,
    validation.error,
    validation.valid,
