  if (chainId.startsWith('aptos:')) {
    return 'mvm';
  }

  return 'evm';}export function WalletConnectScreen({ navigation, route }: WalletConnectScreenProps) {  const { colors } = useTheme();  const styles = useStyles(themeStyles);
