    await waitFor(() => {
      expect(screen.getByText('REVEAL PHRASE')).toBeTruthy();
    });

    fireEvent.press(screen.getByText('REVEAL PHRASE'));

    await waitFor(() => {
      expect(screen.getByText('COPY TO CLIPBOARD')).toBeTruthy();
