class MockWebSocket {
  onopen: any;
  onmessage: any;
  onclose: any;
  onerror: any;
  readyState = 0; // CONNECTING
  url: string;
  constructor(url: string) {
    this.url = url;
    setTimeout(() => {
      this.readyState = 1; // OPEN
      if (this.onopen) this.onopen();
    }, 0);
  }
  close() {
    this.readyState = 3; // CLOSED
    if (this.onclose) this.onclose();
  }
}

// Replace global WebSocket
