      expect(address).toBe(mockAccount.address);
      expect(mnemonicToAccount).toHaveBeenCalledWith('abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon about', { path: "m/44'/60'/0'/0/0" });
    });

