import {
  hasWalletConnectProjectId,
  createWalletConnectSession,
  clearPendingWalletConnectSession,
  onSessionRequest,
  respondToSessionRequest,
  getActiveSessions,
  disconnectSession,
  registerSessionRequestListener,
} from '../walletConnectSession';

describe('walletConnectSession utility tests', () => {
  // Capture a snapshot of original env properties
  const originalEnv = { ...process.env };

  beforeEach(() => {
    jest.clearAllMocks();

    // Clean up process.env without reassigning the process.env object itself
    for (const key in process.env) {
      delete process.env[key];
    }
    Object.assign(process.env, originalEnv);

    // Set a default mock project ID for all tests
    process.env.EXPO_PUBLIC_WALLETCONNECT_PROJECT_ID = 'mock-project-id';
    clearPendingWalletConnectSession();
    mockSignClient.session.values = [];
  });

  afterAll(() => {
    for (const key in process.env) {
      delete process.env[key];
    }
    Object.assign(process.env, originalEnv);
  });

  describe('Project ID checking', () => {
    it('returns false when EXPO_PUBLIC_WALLETCONNECT_PROJECT_ID is missing', () => {
      delete process.env.EXPO_PUBLIC_WALLETCONNECT_PROJECT_ID;
      expect(hasWalletConnectProjectId()).toBe(false);
    });

    it('returns true when EXPO_PUBLIC_WALLETCONNECT_PROJECT_ID is present', () => {
      process.env.EXPO_PUBLIC_WALLETCONNECT_PROJECT_ID = 'mock-project-id';
      expect(hasWalletConnectProjectId()).toBe(true);
    });
  });

  describe('createWalletConnectSession', () => {
    it('throws error if project ID is missing', async () => {
      delete process.env.EXPO_PUBLIC_WALLETCONNECT_PROJECT_ID;
      // We isolate modules to clear the cached signClientPromise
      let freshCreate: any;
      jest.isolateModules(() => {
        freshCreate = require('../walletConnectSession').createWalletConnectSession;
      });
      await expect(freshCreate()).rejects.toThrow(
        'WalletConnect project ID is missing. Set EXPO_PUBLIC_WALLETCONNECT_PROJECT_ID.'
      );
    });

    it('creates session request with normal flow and returns valid approval results', async () => {
      const mockApproval = jest.fn().mockResolvedValue({
        topic: 'test-topic',
        namespaces: {
          eip155: {
            accounts: ['eip155:1:0x1234567890123456789012345678901234567890'],
          },
        },
      });

      mockSignClient.connect.mockResolvedValueOnce({
        uri: 'wc:test-uri',
        approval: mockApproval,
      });

      const sessionRequest = await createWalletConnectSession();

      expect(sessionRequest.uri).toBe('wc:test-uri');
      expect(mockSignClient.connect).toHaveBeenCalled();

      // Test waitForApproval
      const result = await sessionRequest.waitForApproval();
      expect(mockApproval).toHaveBeenCalled();
      expect(result).toEqual({
        topic: 'test-topic',
        account: 'eip155:1:0x1234567890123456789012345678901234567890',
        chainId: 'eip155:1',
        address: '0x1234567890123456789012345678901234567890',
      });
    });

    it('reuses a pending session request if called within the reuse window', async () => {
      mockSignClient.connect.mockResolvedValue({
        uri: 'wc:test-uri-reuse',
        approval: jest.fn(),
      });

      const session1 = await createWalletConnectSession();
      const session2 = await createWalletConnectSession();

      expect(session1.uri).toBe('wc:test-uri-reuse');
      expect(session2.uri).toBe('wc:test-uri-reuse');
      expect(mockSignClient.connect).toHaveBeenCalledTimes(1);
    });

    it('creates a new session request if pending session is cleared', async () => {
      mockSignClient.connect.mockResolvedValue({
        uri: 'wc:test-uri-1',
        approval: jest.fn(),
      });

      await createWalletConnectSession();
      clearPendingWalletConnectSession();

      mockSignClient.connect.mockResolvedValue({
        uri: 'wc:test-uri-2',
        approval: jest.fn(),
      });

      const session2 = await createWalletConnectSession();
      expect(session2.uri).toBe('wc:test-uri-2');
      expect(mockSignClient.connect).toHaveBeenCalledTimes(2);
    });

    it('handles approval timeouts correctly', async () => {
      jest.useFakeTimers();

      // Non-resolving approval mock
      const mockApproval = () => new Promise(() => {});

      mockSignClient.connect.mockResolvedValueOnce({
        uri: 'wc:test-uri-timeout',
        approval: mockApproval,
      });

      const sessionRequest = await createWalletConnectSession({ requestTimeoutMs: 1000 });
      const approvalPromise = sessionRequest.waitForApproval();

      // Fast-forward timers
      jest.advanceTimersByTime(1001);

      await expect(approvalPromise).rejects.toThrow(
        'Wallet connection approval timed out. Please try again.'
      );

      jest.useRealTimers();
    });

    it('extracts primary account with solana/aptos namespace fallbacks', async () => {
      const mockApproval = jest.fn().mockResolvedValue({
        topic: 'solana-topic',
        namespaces: {
          solana: {
            accounts: ['solana:5eyktz9u97L777:HN7cAB21StwBua29A322ss'],
          },
        },
      });

      mockSignClient.connect.mockResolvedValueOnce({
        uri: 'wc:solana-uri',
        approval: mockApproval,
      });

      const sessionRequest = await createWalletConnectSession();
      const result = await sessionRequest.waitForApproval();

      expect(result).toEqual({
        topic: 'solana-topic',
        account: 'solana:5eyktz9u97L777:HN7cAB21StwBua29A322ss',
        chainId: 'solana:5eyktz9u97L777',
        address: 'HN7cAB21StwBua29A322ss',
      });
    });

    it('gracefully handles missing namespace primary accounts', async () => {
      const mockApproval = jest.fn().mockResolvedValue({
        topic: 'empty-topic',
        namespaces: {},
      });

      mockSignClient.connect.mockResolvedValueOnce({
        uri: 'wc:empty-uri',
        approval: mockApproval,
      });

      const sessionRequest = await createWalletConnectSession();
      const result = await sessionRequest.waitForApproval();

      expect(result).toEqual({
        topic: 'empty-topic',
        account: null,
        chainId: null,
        address: null,
      });
    });
  });

  describe('respondToSessionRequest', () => {
    it('sends success result through SignClient respond', async () => {
      await respondToSessionRequest('test-topic', {
        id: 42,
        result: '0xsignature_hash',
      });

      expect(mockSignClient.respond).toHaveBeenCalledWith({
        topic: 'test-topic',
        response: {
          id: 42,
          result: '0xsignature_hash',
        },
      });
    });

    it('sends error through SignClient respond if error payload exists', async () => {
      await respondToSessionRequest('test-topic', {
        id: 42,
        result: null,
        error: { code: 4001, message: 'User rejected' },
      });

      expect(mockSignClient.respond).toHaveBeenCalledWith({
        topic: 'test-topic',
        response: {
          id: 42,
          error: { code: 4001, message: 'User rejected' },
        },
      });
    });
  });

  describe('getActiveSessions and disconnectSession', () => {
    it('fetches all active sessions from SignClient values/map', async () => {
      mockSignClient.session.values = [{ topic: 's1' }, { topic: 's2' }];

      const sessions = await getActiveSessions();
      expect(sessions).toHaveLength(2);
      expect(sessions[0].topic).toBe('s1');
    });

    it('triggers disconnect trigger through SignClient disconnect', async () => {
      await disconnectSession('target-topic');

      expect(mockSignClient.disconnect).toHaveBeenCalledWith({
        topic: 'target-topic',
        reason: { code: 6000, message: 'User disconnected' },
      });
    });
  });

  describe('onSessionRequest handlers and session listeners', () => {
    it('manages listener registries and responds to callbacks', async () => {
      const mockHandler = jest.fn();
      const unsubscribe = onSessionRequest(mockHandler);

      let registeredCallback: ((event: any) => void) | null = null;
      mockSignClient.on.mockImplementation((event: string, callback: any) => {
        if (event === 'session_request') {
          registeredCallback = callback;
        }
      });

      await registerSessionRequestListener();
      expect(mockSignClient.on).toHaveBeenCalledWith('session_request', expect.any(Function));

      // Trigger the mock event callback
      if (registeredCallback) {
        (registeredCallback as any)({
          topic: 'callback-topic',
          params: {
            request: {
              method: 'eth_sign',
              params: ['hello'],
            },
            chainId: 'eip155:1',
          },
        });
      }

      expect(mockHandler).toHaveBeenCalledWith({
        topic: 'callback-topic',
        request: {
          method: 'eth_sign',
          params: ['hello'],
        },
        chainId: 'eip155:1',
      });

      unsubscribe();
    });
  });
});

/* istanbul ignore file */
import {
  ANALYTICS_EVENTS,
  type AnalyticsEventName,
  type AnalyticsEventPayloadMap,
  type AnalyticsPayload,
} from './analyticsEvents';

type EventPayload<K extends AnalyticsEventName> = AnalyticsEventPayloadMap[K];

type RequiredPayloadEvents = {
  [K in AnalyticsEventName]: undefined extends EventPayload<K> ? never : K;
}[AnalyticsEventName];

type OptionalPayloadEvents = Exclude<AnalyticsEventName, RequiredPayloadEvents>;

type MixpanelClient = {
  init: () => Promise<void>;
  track: (eventName: string, payload?: AnalyticsPayload) => void;
  identify?: (id: string) => void;
  reset?: () => void;
  getPeople?: () => {
    set: (payload: AnalyticsPayload) => void;
  };
  optInTracking?: () => void;
  optOutTracking?: () => void;
};

const analyticsEnabled = process.env.EXPO_PUBLIC_ENABLE_ANALYTICS === 'true';
const mixpanelToken = (process.env.EXPO_PUBLIC_MIXPANEL_TOKEN || '').trim();
let userAnalyticsConsent = false;

let mixpanel: MixpanelClient | null = null;
let initPromise: Promise<boolean> | null = null;
let hasWarnedMissingToken = false;

function shouldEnableAnalytics(): boolean {
  return analyticsEnabled && userAnalyticsConsent && mixpanelToken.length > 0;
}

function hasRuntimeAnalyticsEnabled(): boolean {
  return analyticsEnabled && userAnalyticsConsent;
}

export function setAnalyticsConsent(enabled: boolean) {
  userAnalyticsConsent = enabled;

  if (mixpanel) {
    if (enabled) {
      mixpanel.optInTracking?.();
    } else {
      mixpanel.reset?.();
      mixpanel.optOutTracking?.();
    }
  }

  if (__DEV__) {
    console.log('[analytics:consent]', enabled ? 'enabled' : 'disabled');
  }
}

export async function initAnalytics(): Promise<boolean> {
  if (mixpanel) {
    if (!hasRuntimeAnalyticsEnabled()) {
      mixpanel.optOutTracking?.();
      return false;
    }

    return true;
  }

  if (!shouldEnableAnalytics()) {
    if (__DEV__ && analyticsEnabled && userAnalyticsConsent && mixpanelToken.length === 0 && !hasWarnedMissingToken) {
      hasWarnedMissingToken = true;
      console.warn('[analytics] EXPO_PUBLIC_MIXPANEL_TOKEN missing; analytics disabled.');
    }
    return false;
  }

  if (initPromise) {
    return initPromise;
  }

  initPromise = (async () => {
    try {
      const { Mixpanel } = await import('mixpanel-react-native');
      const client = new Mixpanel(mixpanelToken, false) as MixpanelClient;
      await client.init();
      client.optInTracking?.();
      mixpanel = client;

      if (__DEV__) {
        console.log('[analytics] Mixpanel initialized');
      }

      return true;
    } catch (error) {
      if (__DEV__) {
        console.warn('[analytics] Failed to initialize Mixpanel', error);
      }
      return false;
    }
  })();

  return initPromise;
}

async function withMixpanel(run: (client: MixpanelClient) => void): Promise<void> {
  const ready = await initAnalytics();
  if (!ready || !mixpanel) {
    return;
  }

  run(mixpanel);
}

export function trackEvent<K extends RequiredPayloadEvents>(
  eventName: K,
  payload: EventPayload<K>
): void;
export function trackEvent<K extends OptionalPayloadEvents>(
  eventName: K,
  payload?: EventPayload<K>
): void;
export function trackEvent(eventName: AnalyticsEventName, payload?: AnalyticsPayload) {
  if (!hasRuntimeAnalyticsEnabled()) {
    return;
  }

  void withMixpanel((client) => {
    client.track(eventName, payload || {});
  });

  if (__DEV__) {
    console.log('[analytics:event]', eventName, payload || {});
  }
}

export function trackScreenView(screenName: string, payload?: AnalyticsPayload) {
  trackEvent(ANALYTICS_EVENTS.SCREEN_VIEW, {
    screen_name: screenName,
    ...payload,
  });
}

export function trackTypedEvent<K extends AnalyticsEventName>(
  eventName: K,
  ...[payload]: undefined extends EventPayload<K>
    ? [payload?: EventPayload<K>]
    : [payload: EventPayload<K>]
) {
  (trackEvent as (eventName: AnalyticsEventName, payload?: AnalyticsPayload) => void)(
    eventName,
    payload as AnalyticsPayload | undefined
  );
}

export function identifyUser(userId: string, traits?: AnalyticsPayload) {
  if (!hasRuntimeAnalyticsEnabled() || !userId) {
    return;
  }

  void withMixpanel((client) => {
    client.identify?.(userId);
    client.getPeople?.().set({
      wallet_address: userId,
      ...traits,
    });
  });

  if (__DEV__) {
    console.log('[analytics:user]', userId, traits || {});
  }
}

export function resetAnalyticsUser() {
  if (!analyticsEnabled) {
    return;
  }

  if (mixpanel) {
    mixpanel.reset?.();

    if (!userAnalyticsConsent) {
      mixpanel.optOutTracking?.();
    }

    return;
  }

  void withMixpanel((client) => {
    client.reset?.();
  });
}

import { Aptos, AptosConfig, Network, Account } from '@aptos-labs/ts-sdk';
import { getStoredMnemonic, TransactionError, NETWORKS } from './transactions';
import { captureError, addBreadcrumb } from './sentry';
import type { SignerParams, SignerResult } from './secureSigner';
import type { GasEstimate } from './gasEstimator';
import { getRpcUrl } from './rpc';

export async function signAndSendAptosTransaction(
  params: SignerParams,
  chainKey: string,
  ethPrice?: number
): Promise<SignerResult> {
  addBreadcrumb('Aptos transaction signing initiated', 'transaction', { chain: chainKey });

  const network = NETWORKS[chainKey];
  if (!network || network.symbol !== 'APT') {
    throw new TransactionError(`Unsupported Aptos network: ${chainKey}.`, 'UNKNOWN');
  }

  // Parse value to Octas (Aptos decimals = 8)
  const amountOctas = BigInt(Math.floor(parseFloat(params.value) * 1e8));
  if (amountOctas <= 0n) {
    throw new TransactionError('Transaction value must be greater than zero', 'UNKNOWN');
  }

  const mnemonicWords = await getStoredMnemonic();
  if (!mnemonicWords || mnemonicWords.length === 0) {
    throw new TransactionError('No wallet found. Please create or import a wallet first.', 'UNKNOWN');
  }

  let txResult: SignerResult;
  try {
    const mnemonicPhrase = mnemonicWords.join(' ');
    const account = Account.fromDerivationPath({ path: "m/44'/634'/0'/0'/0'", mnemonic: mnemonicPhrase });

    const rpcUrl = getRpcUrl(chainKey);
    // Determine the AptosNetwork enum
    let aptosNetwork = Network.MAINNET;
    if (chainKey.includes('testnet')) aptosNetwork = Network.TESTNET;
    else if (chainKey.includes('devnet')) aptosNetwork = Network.DEVNET;

    const aptosConfig = new AptosConfig({ network: aptosNetwork, fullnode: rpcUrl });
    const aptos = new Aptos(aptosConfig);

    // Build the simple transfer transaction
    const transaction = await aptos.transaction.build.simple({
      sender: account.accountAddress,
      data: {
        function: '0x1::aptos_account::transfer',
        functionArguments: [params.to, amountOctas],
      },
    });

    // Sign the transaction
    const senderAuthenticator = aptos.transaction.sign({
      signer: account,
      transaction,
    });

    // Submit the transaction
    const pendingTransaction = await aptos.transaction.submit.simple({
      transaction,
      senderAuthenticator,
    });

    // Wait for the transaction to be processed (optional but good for getting gas used)
    const executedTransaction = await aptos.waitForTransaction({ transactionHash: pendingTransaction.hash });

    // We can also just use the submitted hash immediately
    const signature = pendingTransaction.hash;

    const estimatedCostWei = 200000n; // mock fallback
    const estimatedCostEth = '0.0002'; // mock fallback

    const gasEstimate: GasEstimate = {
      gasLimit: 2000n,
      maxFeePerGas: 100n,
      maxPriorityFeePerGas: 0n,
      gasPrice: 100n,
      estimatedCostWei,
      estimatedCostEth,
      estimatedCostUsd: ethPrice ? (0.0002 * ethPrice).toFixed(4) : null,
      isStale: false,
      fetchedAt: Date.now(),
    };

    txResult = {
      hash: signature,
      chainId: network.chainId,
      gasEstimate,
    };

    addBreadcrumb('Aptos transaction broadcast successful', 'transaction', {
      chain: chainKey,
      txHash: signature,
    });
  } catch (err) {
    if (err instanceof TransactionError) throw err;
    const message = (err as any)?.message || 'Unknown signing error';
    captureError(new Error(message), { scope: 'aptos-signer', chain: chainKey });
    throw new TransactionError(message, 'UNKNOWN');
  }

  return txResult;
}

