import { Linking } from 'react-native';

export type WalletChainType = 'evm' | 'svm' | 'mvm';

export type DeepLinkParams = {
  action: 'send' | 'receive' | 'approve' | 'reject' | 'walletconnect' | 'transactions';
  address?: string;
  chainType?: WalletChainType;
  amount?: string;
  token?: string;
  uri?: string;
  transactionHash?: string;
  transactionId?: string;
};

const ACTIONS: DeepLinkParams['action'][] = [
  'send',
  'receive',
  'approve',
  'reject',
  'walletconnect',
  'transactions',
];

// M2 fix: validate incoming address parameters to prevent injection of attacker addresses.
// EVM: 0x + 40 hex chars. Solana: base58 32-44 chars. Aptos: 0x + 64 hex chars.
const ADDRESS_PATTERNS: Record<WalletChainType | 'unknown', RegExp> = {
  evm: /^0x[0-9a-fA-F]{40}$/,
  mvm: /^0x[0-9a-fA-F]{64}$/,
  svm: /^[1-9A-HJ-NP-Za-km-z]{32,44}$/,
  unknown: /^(0x[0-9a-fA-F]{40}|0x[0-9a-fA-F]{64}|[1-9A-HJ-NP-Za-km-z]{32,44})$/,
};

function validateAddress(address: string, chainType?: WalletChainType): boolean {
  const pattern = chainType ? ADDRESS_PATTERNS[chainType] : ADDRESS_PATTERNS.unknown;
  return pattern.test(address);
}

function parseQueryParams(queryString: string): Record<string, string> {
  if (!queryString) {
    return {};
  }

  return queryString
    .split('&')
    .filter(Boolean)
    .reduce<Record<string, string>>((acc, pair) => {
      const [rawKey, rawValue = ''] = pair.split('=');
      if (!rawKey) {
        return acc;
      }

      const key = decodeURIComponent(rawKey);
      const value = decodeURIComponent(rawValue);
      acc[key] = value;
      return acc;
    }, {});
}

export function parseDeepLink(url: string): DeepLinkParams | null {
  try {
    if (!url.startsWith('veilpay://')) {
      return null;
    }

    let action = '';
    let queryParams: Record<string, string> = {};

    try {
      const parsedUrl = new URL(url);
      if (parsedUrl.protocol !== 'veilpay:') {
        return null;
      }

      action = parsedUrl.hostname.toLowerCase();
      queryParams = parseQueryParams(parsedUrl.search.replace(/^\?/, ''));
    } catch {
      const stripped = url.replace('veilpay://', '');
      const [host, rawQuery = ''] = stripped.split('?');
      action = host.toLowerCase();
      queryParams = parseQueryParams(rawQuery);
    }

    const typedAction = action as DeepLinkParams['action'];
    if (!ACTIONS.includes(typedAction)) {
      return null;
    }

    const params: DeepLinkParams = {
      action: typedAction,
    };

    const address = queryParams.address;
    const amount = queryParams.amount;
    const token = queryParams.token;
    const uri = queryParams.uri;
    const chainType = queryParams.chainType;
    const transactionHash = queryParams.transactionHash || queryParams.hash;
    const transactionId = queryParams.transactionId || queryParams.txId;

    if (chainType === 'evm' || chainType === 'svm' || chainType === 'mvm') {
      params.chainType = chainType;
    }

    // M2 fix: validate address format before accepting it from the deep link.
    // An attacker could craft veilpay://send?address=<attacker_address> to pre-fill
    // an attacker-controlled address in the send flow.
    if (address) {
      if (!validateAddress(address, params.chainType)) {
        console.warn('[deepLink] Rejected invalid address from deep link:', address);
        return null;
      }
      params.address = address;
    }

    if (amount) {
      // Only accept numeric amounts (including decimals); reject arbitrary strings.
      if (!/^\d+(\.\d{1,18})?$/.test(amount)) {
        console.warn('[deepLink] Rejected non-numeric amount from deep link:', amount);
        return null;
      }
      // Cap amount to a reasonable maximum (1 billion ETH) to prevent absurd pre-fills
      const parsedAmount = parseFloat(amount);
      if (!Number.isFinite(parsedAmount) || parsedAmount <= 0 || parsedAmount > 1e9) {
        console.warn('[deepLink] Rejected out-of-range amount from deep link:', amount);
        return null;
      }
      // Normalize: strip trailing zeros after decimal point to prevent format tricks
      params.amount = parsedAmount.toString();
    }
    if (token) {
      // Only accept alphanumeric token symbols (e.g. "ETH", "USDC", "wETH")
      // Reject anything with special chars, URLs, or script-like content
      if (!/^[a-zA-Z0-9]{1,20}$/.test(token)) {
        console.warn('[deepLink] Rejected invalid token symbol from deep link:', token);
        return null;
      }
      params.token = token;
    }
  if (uri) {
    // Only accept WalletConnect URIs (wc: prefix) to prevent arbitrary URL injection
    if (!uri.startsWith('wc:')) {
      console.warn('[deepLink] Rejected non-WalletConnect URI from deep link:', uri.substring(0, 20));
      return null;
    }
    if (uri.length > 2048) {
      console.warn('[deepLink] Rejected WalletConnect URI exceeding 2048 chars from deep link');
      return null;
    }
    params.uri = uri;
  }
    if (transactionHash) {
      // Validate tx hash format: 0x + 64 hex chars (EVM) or base58 (SVM)
      if (!/^0x[0-9a-fA-F]{64}$/.test(transactionHash) && !/^[1-9A-HJ-NP-Za-km-z]{88}$/.test(transactionHash)) {
        console.warn('[deepLink] Rejected invalid transactionHash from deep link:', transactionHash.substring(0, 20));
        return null;
      }
      params.transactionHash = transactionHash;
    }
    if (transactionId) {
      // Transaction IDs are backend-generated; accept alphanumeric + hyphens, max 128 chars
      if (!/^[a-zA-Z0-9_-]{1,128}$/.test(transactionId)) {
        console.warn('[deepLink] Rejected invalid transactionId from deep link:', transactionId.substring(0, 20));
        return null;
      }
      params.transactionId = transactionId;
    }

    return params;
  } catch (error) {
    console.error('Failed to parse deep link:', error);
    return null;
  }
}

export function setupDeepLinking(handler: (params: DeepLinkParams) => void) {
  // Handle initial URL if app was opened via deep link
  Linking.getInitialURL().then((url) => {
    if (url) {
      const params = parseDeepLink(url);
      if (params) {
        handler(params);
      }
    }
  });

  // Handle deep links while app is running
  const subscription = Linking.addEventListener('url', ({ url }) => {
    const params = parseDeepLink(url);
    if (params) {
      handler(params);
    }
  });

  return () => subscription.remove();
}

export function createSendLink(address: string, amount: string, token?: string): string {
  let url = `veilpay://send?address=${encodeURIComponent(address)}&amount=${encodeURIComponent(amount)}`;
  if (token) {
    url += `&token=${encodeURIComponent(token)}`;
  }
  return url;
}

export function createReceiveLink(address: string): string {
  return `veilpay://receive?address=${encodeURIComponent(address)}`;
}

export function createWalletConnectLink(
  uri: string,
  options?: {
    address?: string;
    chainType?: WalletChainType;
  }
): string {
  const query = new URLSearchParams();
  query.set('uri', uri);

  if (options?.address) {
    query.set('address', options.address);
  }
  if (options?.chainType) {
    query.set('chainType', options.chainType);
  }

  return `veilpay://walletconnect?${query.toString()}`;
}

export function createTransactionLink(transactionHash: string): string {
  return `veilpay://transactions?hash=${encodeURIComponent(transactionHash)}`;
}

import nacl from 'tweetnacl';
import { Buffer } from 'buffer';

export interface EncryptedNote {
  nonce: string; // base64
  ciphertext: string; // base64
}

/**
 * Generates an ephemeral Curve25519 keypair for encryption purposes.
 */
export function generateEphemeralKeyPair() {
  const keyPair = nacl.box.keyPair();
  return {
    publicKey: keyPair.publicKey,
    secretKey: keyPair.secretKey,
  };
}

/**
 * Encrypts a plaintext memo for a specific recipient using NaCl Box (Curve25519-XSalsa20-Poly1305).
 * 
 * @param memo The plaintext message
 * @param recipientPublicKey The receiver's public key (32 bytes)
 * @param senderSecretKey The sender's private key (32 bytes)
 */
export function encryptNote(
  memo: string,
  recipientPublicKey: Uint8Array,
  senderSecretKey: Uint8Array
): EncryptedNote {
  const nonce = nacl.randomBytes(nacl.box.nonceLength);
  const messageUint8 = Buffer.from(memo, 'utf8');

  const encryptedMessage = nacl.box(
    messageUint8,
    nonce,
    recipientPublicKey,
    senderSecretKey
  );

  return {
    nonce: Buffer.from(nonce).toString('base64'),
    ciphertext: Buffer.from(encryptedMessage).toString('base64'),
  };
}

/**
 * Decrypts an encrypted memo using the recipient's secret key and the sender's public key.
 */
export function decryptNote(
  encryptedNote: EncryptedNote,
  senderPublicKey: Uint8Array,
  recipientSecretKey: Uint8Array
): string | null {
  const nonce = Buffer.from(encryptedNote.nonce, 'base64');
  const ciphertext = Buffer.from(encryptedNote.ciphertext, 'base64');

  const decryptedMessage = nacl.box.open(
    ciphertext,
    nonce,
    senderPublicKey,
    recipientSecretKey
  );

  if (!decryptedMessage) {
    return null;
  }

  return Buffer.from(decryptedMessage).toString('utf8');
}

/**
 * Veilpay Environment Validation
 *
 * Validates required environment variables at app startup.
 * Fails fast with a user-friendly message if critical config is missing.
 *
 * Priority levels:
 * - CRITICAL: App cannot function (no RPC, no backend)
 * - IMPORTANT: Feature degraded but app usable (no analytics, no WalletConnect)
 * - OPTIONAL: Nice-to-have (Sentry, OTA updates)
 */

export type EnvValidationLevel = 'critical' | 'important' | 'optional';

export interface EnvValidationResult {
  isValid: boolean;
  errors: EnvValidationError[];
  warnings: EnvValidationWarning[];
}

export interface EnvValidationError {
  key: string;
  level: EnvValidationLevel;
  message: string;
  userMessage: string;
}

export interface EnvValidationWarning {
  key: string;
  message: string;
}

interface EnvVarSpec {
  key: string;
  level: EnvValidationLevel;
  description: string;
  userMessage: string;
  validate?: (value: string) => boolean;
}

const ENV_SPECS: EnvVarSpec[] = [
  // ── CRITICAL: App cannot function without these ──────────────────────────
  {
    key: 'EXPO_PUBLIC_BACKEND_BASE_URL',
    level: 'critical',
    description: 'Backend API base URL for transaction history and push registration',
    userMessage: 'Backend server URL is not configured. Transaction history and notifications will not work.',
    validate: (v) => {
      if (!v) return false;
      try {
        new URL(v);
        return true;
      } catch {
        return false;
      }
    },
  },
  {
    key: 'EXPO_PUBLIC_ALCHEMY_API_KEY',
    level: 'critical',
    description: 'Alchemy API key for reliable RPC access (free tier: 300M CU/month)',
    userMessage: 'No RPC API key configured. Blockchain connections will use unreliable public endpoints and may fail.',
  },
  {
    key: 'EXPO_PUBLIC_INFURA_API_KEY',
    level: 'important',
    description: 'Infura API key for RPC failover (free tier: 100K req/day)',
    userMessage: 'No Infura backup key configured. RPC failover will rely on public endpoints only.',
  },

  // ── IMPORTANT: Feature degraded but app usable ────────────────────────────
  {
    key: 'EXPO_PUBLIC_WALLETCONNECT_PROJECT_ID',
    level: 'important',
    description: 'WalletConnect Cloud project ID for dApp connections',
    userMessage: 'WalletConnect is not configured. You won\'t be able to connect to external dApps.',
  },
  {
    key: 'EXPO_PUBLIC_SENTRY_DSN',
    level: 'important',
    description: 'Sentry DSN for production crash reporting',
    userMessage: 'Crash reporting is not configured. Errors won\'t be reported to the team.',
  },
  {
    key: 'EXPO_PUBLIC_EAS_PROJECT_ID',
    level: 'important',
    description: 'EAS project ID for OTA updates',
    userMessage: 'Over-the-air updates are not configured. You\'ll need to reinstall for updates.',
  },

  // ── OPTIONAL: Nice-to-have ───────────────────────────────────────────────
  {
    key: 'EXPO_PUBLIC_MIXPANEL_TOKEN',
    level: 'optional',
    description: 'Mixpanel token for analytics tracking',
    userMessage: 'Analytics tracking is not configured.',
  },
  {
    key: 'EXPO_PUBLIC_EAS_UPDATE_URL',
    level: 'optional',
    description: 'EAS update URL for OTA update checks',
    userMessage: 'OTA update URL not set.',
  },
];

/**
 * Validates all environment variables and returns a structured result.
 *
 * The app should check `result.isValid` before proceeding.
 * If invalid, display the `userMessage` from each error.
 */
export function validateEnvironment(): EnvValidationResult {
  const errors: EnvValidationError[] = [];
  const warnings: EnvValidationWarning[] = [];

  for (const spec of ENV_SPECS) {
    const value = (process.env[spec.key] || '').trim();
    const isPresent = spec.validate ? spec.validate(value) : value.length > 0;

    if (!isPresent) {
      if (spec.level === 'critical') {
        errors.push({
          key: spec.key,
          level: spec.level,
          message: `Missing or invalid: ${spec.key} — ${spec.description}`,
          userMessage: spec.userMessage,
        });
      } else if (spec.level === 'important') {
        warnings.push({
          key: spec.key,
          message: spec.userMessage,
        });
      }
      // optional: silently skip
    }
  }

  // In development mode, relax critical requirements
  // (public RPC endpoints are acceptable for testing)
  const isDev = __DEV__;
  const criticalErrors = isDev
    ? errors.filter((e) => {
        // In dev, only EXPO_PUBLIC_BACKEND_BASE_URL is truly critical
        // (public RPCs work fine for testing)
        return e.key === 'EXPO_PUBLIC_BACKEND_BASE_URL';
      })
    : errors;

  return {
    isValid: criticalErrors.length === 0,
    errors: criticalErrors,
    warnings,
  };
}

/**
 * Returns a user-friendly summary of all validation issues.
 * Suitable for displaying in an Alert or on-screen message.
 */
export function getEnvValidationSummary(result: EnvValidationResult): string {
  const parts: string[] = [];

  if (result.errors.length > 0) {
    parts.push('⚠️ Configuration Issues:');
    for (const error of result.errors) {
      parts.push(`• ${error.userMessage}`);
    }
  }

  if (result.warnings.length > 0) {
    parts.push('');
    parts.push('ℹ️ Optional Features:');
    for (const warning of result.warnings) {
      parts.push(`• ${warning.message}`);
    }
  }

  return parts.join('\n');
}

import { Platform } from 'react-native';
import * as Haptics from 'expo-haptics';

function canTriggerHaptics(): boolean {
  return Platform.OS !== 'web';
}

export async function triggerLightImpactHaptic() {
  if (!canTriggerHaptics()) {
    return;
  }

  try {
    await Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
  } catch (error) {
    if (__DEV__) {
      console.warn('[haptics] Failed to trigger light impact', error);
    }
  }
}

export async function triggerNotificationHaptic(type: Haptics.NotificationFeedbackType) {
  if (!canTriggerHaptics()) {
    return;
  }

  try {
    await Haptics.notificationAsync(type);
  } catch (error) {
    if (__DEV__) {
      console.warn('[haptics] Failed to trigger notification', error);
    }
  }
}

import AsyncStorage from '@react-native-async-storage/async-storage';
import { sleep } from './timing';

export type MarketQuoteSource = 'binance' | 'cache' | 'fallback';

export interface MarketQuote {
  symbol: string;
  price: number;
  change24h: number | null;
  lastUpdated: number;
  source: MarketQuoteSource;
  isStale: boolean;
}

export type MarketQuoteMap = Record<string, MarketQuote>;

type MarketSnapshot = {
  usd?: number;
  usd_24h_change?: number;
};

const CACHE_KEY = '@veilpay_market_data_cache_v1';
const CACHE_TTL_MS = 5 * 60 * 1000;

const BINANCE_SYMBOLS: Record<string, string> = {
  ETH: 'ETHUSDT',
  MATIC: 'MATICUSDT',
  SOL: 'SOLUSDT',
  APT: 'APTUSDT',
  USDC: 'USDCUSDT',
  DAI: 'DAIUSDT',
  BNB: 'BNBUSDT',
  AVAX: 'AVAXUSDT',
  TRX: 'TRXUSDT',
  XLM: 'XLMUSDT',
};

const FALLBACK_QUOTES: Record<string, { price: number; change24h: number | null }> = {
  ETH: { price: 3200, change24h: null },
  MATIC: { price: 0.9, change24h: null },
  SOL: { price: 140, change24h: null },
  APT: { price: 8.5, change24h: null },
  BNB: { price: 580, change24h: null },
  AVAX: { price: 35, change24h: null },
  TRX: { price: 0.12, change24h: null },
  XLM: { price: 0.11, change24h: null },
  USDT: { price: 1, change24h: 0 },
  USDC: { price: 1, change24h: 0 },
  DAI: { price: 1, change24h: 0 },
};

const memoryCache: MarketQuoteMap = {};
let hasLoadedCache = false;
const inFlightRequests = new Map<string, Promise<MarketQuoteMap>>();

function normalizeSymbols(symbols: readonly string[]): string[] {
  return Array.from(    new Set(      symbols
        .map((symbol) => symbol.trim().toUpperCase())
        .filter((symbol) => symbol.length > 0)
    )
  ).sort();
}

function buildRequestKey(symbols: readonly string[]): string {
  return normalizeSymbols(symbols).join('|');
}

function isFresh(quote: MarketQuote): boolean {
  if (quote.source === 'fallback') {
    return false;
  }

  return Date.now() - quote.lastUpdated < CACHE_TTL_MS;
}

function createFallbackQuote(symbol: string): MarketQuote {
  const normalized = symbol.trim().toUpperCase();
  const fallback = FALLBACK_QUOTES[normalized] ?? { price: 0, change24h: null };

  return {
    symbol: normalized,
    price: fallback.price,
    change24h: fallback.change24h,
    lastUpdated: Date.now(),
    source: 'fallback',
    isStale: true,
  };
}

export function createFallbackQuoteMap(symbols: readonly string[]): MarketQuoteMap {
  const map: MarketQuoteMap = {};

  for (const symbol of normalizeSymbols(symbols)) {
    map[symbol] = createFallbackQuote(symbol);
  }

  return map;
}

async function loadCache(): Promise<void> {
  if (hasLoadedCache) {
    return;
  }

  hasLoadedCache = true;

  try {
    const cached = await AsyncStorage.getItem(CACHE_KEY);
    if (!cached) {
      return;
    }

    const parsed = JSON.parse(cached) as MarketQuoteMap;
    for (const [symbol, quote] of Object.entries(parsed)) {
      if (!quote || typeof quote.price !== 'number') {
        continue;
      }

      memoryCache[symbol] = {
        symbol,
        price: quote.price,
        change24h: typeof quote.change24h === 'number' ? quote.change24h : null,
        lastUpdated: typeof quote.lastUpdated === 'number' ? quote.lastUpdated : Date.now(),
        source: quote.source === 'fallback' ? 'fallback' : 'cache',
        isStale: quote.source === 'fallback' ? true : !isFresh(quote),
      };
    }
  } catch (error) {
    console.warn('Failed to load market data cache:', error);
  }
}

async function persistCache(): Promise<void> {
  try {
    await AsyncStorage.setItem(CACHE_KEY, JSON.stringify(memoryCache));
  } catch (error) {
    console.warn('Failed to persist market data cache:', error);
  }
}

function mergeQuote(symbol: string, nextQuote: MarketQuote): MarketQuote {
  const normalized = symbol.trim().toUpperCase();
  const merged: MarketQuote = {
    symbol: normalized,
    price: nextQuote.price,
    change24h: nextQuote.change24h,
    lastUpdated: nextQuote.lastUpdated,
    source: nextQuote.source,
    isStale: nextQuote.isStale,
  };

  memoryCache[normalized] = merged;
  return merged;
}

export function updateLiveQuote(symbol: string, price: number, change24h: number | null): void {
  const normalized = symbol.trim().toUpperCase();
  mergeQuote(normalized, {
    symbol: normalized,
    price,
    change24h,
    lastUpdated: Date.now(),
    source: 'binance',
    isStale: false,
  });
}

/** Binance API retry config */
const BINANCE_MAX_RETRIES = 2;
const BINANCE_RETRY_BASE_DELAY_MS = 1000;

interface BinanceTicker {
  symbol: string;
  lastPrice: string;
  priceChangePercent: string;
}

async function fetchFromBinance(symbols: readonly string[]): Promise<MarketQuoteMap> {
  const normalizedSymbols = normalizeSymbols(symbols);
  const binanceSymbols = normalizedSymbols
    .map((symbol) => BINANCE_SYMBOLS[symbol])
    .filter((s): s is string => Boolean(s));

  if (binanceSymbols.length === 0) {
    return createFallbackQuoteMap(normalizedSymbols);
  }

  // Binance API supports multiple symbols in one request via JSON array in query
  const symbolsJson = JSON.stringify(binanceSymbols);
  const url = `https://api.binance.com/api/v3/ticker/24hr?symbols=${encodeURIComponent(symbolsJson)}`;

  let data: BinanceTicker[] | null = null;  for (let attempt = 0; attempt <= BINANCE_MAX_RETRIES; attempt++) {
    try {      const response = await fetch(url, {
        method: 'GET',
        headers: {
          Accept: 'application/json',
        },
      });

      if (response.ok) {
        data = (await response.json()) as BinanceTicker[];
        break;
      }

      if (response.status === 429 && attempt < BINANCE_MAX_RETRIES) {
        const delayMs = BINANCE_RETRY_BASE_DELAY_MS * Math.pow(2, attempt);
        await sleep(delayMs);
        continue;
      }

      throw new Error(`Binance API error: ${response.status}`);
    } catch (error) {
      if (attempt === BINANCE_MAX_RETRIES) throw error;
      const delayMs = BINANCE_RETRY_BASE_DELAY_MS * Math.pow(2, attempt);
      await sleep(delayMs);
    }
  }

  if (!data) {
    throw new Error('Binance API error: Data not received after retries');
  }

  const now = Date.now();
  const quotes: MarketQuoteMap = {};
  const dataMap = new Map(data.map((item) => [item.symbol, item]));

  for (const symbol of normalizedSymbols) {
    const binanceSymbol = BINANCE_SYMBOLS[symbol];
    const ticker = binanceSymbol ? dataMap.get(binanceSymbol) : undefined;

    if (ticker && ticker.lastPrice) {
      const price = parseFloat(ticker.lastPrice);
      const change = parseFloat(ticker.priceChangePercent);

      quotes[symbol] = mergeQuote(symbol, {
        symbol,
        price,
        change24h: isNaN(change) ? null : change,
        lastUpdated: now,
        source: 'binance',
        isStale: false,
      });
      continue;    }

    // Special case for stablecoins if they failed or aren't mapped    if (['USDT', 'USDC', 'DAI'].includes(symbol)) {
       quotes[symbol] = mergeQuote(symbol, {
         symbol,
         price: 1,
         change24h: 0,
         lastUpdated: now,
         source: 'binance',
         isStale: false,
       });
       continue;
    }

    quotes[symbol] = memoryCache[symbol] ?? createFallbackQuote(symbol);
  }

  await persistCache();
  return quotes;
}

function getCachedQuotes(symbols: readonly string[]): MarketQuoteMap {
  const normalizedSymbols = normalizeSymbols(symbols);
  const quotes: MarketQuoteMap = {};

  for (const symbol of normalizedSymbols) {
    const cached = memoryCache[symbol];
    if (cached) {
      quotes[symbol] = {
        ...cached,
        source: cached.source === 'fallback' ? 'fallback' : 'cache',
        isStale: !isFresh(cached),
      };
      continue;
    }

    quotes[symbol] = createFallbackQuote(symbol);
  }

  return quotes;
}

export async function getTokenMarketData(
  symbols: readonly string[],
  options: { preferCache?: boolean } = {}
): Promise<MarketQuoteMap> {
  const normalizedSymbols = normalizeSymbols(symbols);

  if (normalizedSymbols.length === 0) {
    return {};
  }

  await loadCache();

  const cachedQuotes = getCachedQuotes(normalizedSymbols);
  const allFresh = normalizedSymbols.every((symbol) => {
    const cached = memoryCache[symbol];
    return Boolean(cached && isFresh(cached));
  });

  if (options.preferCache && allFresh) {
    return cachedQuotes;
  }

  const requestKey = buildRequestKey(normalizedSymbols);
  const inFlight = inFlightRequests.get(requestKey);

  if (inFlight) {
    return inFlight;
  }

  const request = (async () => {
    try {
      const liveQuotes = await fetchFromBinance(normalizedSymbols);
      return liveQuotes;
    } catch (error) {
      console.warn('Failed to fetch live market data:', error);
      return cachedQuotes;
    } finally {
      inFlightRequests.delete(requestKey);
    }
  })();

  inFlightRequests.set(requestKey, request);
  return request;
}

export async function getTokenMarketQuote(
  symbol: string,
  options: { preferCache?: boolean } = {}
): Promise<MarketQuote> {
  const normalized = symbol.trim().toUpperCase();
  const quotes = await getTokenMarketData([normalized], options);
  return quotes[normalized] ?? createFallbackQuote(normalized);
}

export function getCachedTokenMarketQuote(symbol: string): MarketQuote {
  const normalized = symbol.trim().toUpperCase();
  const cached = memoryCache[normalized];

  if (cached) {
    return {
      ...cached,
      source: cached.source === 'fallback' ? 'fallback' : 'cache',
      isStale: !isFresh(cached),
    };
  }

  return createFallbackQuote(normalized);
}

import { updateLiveQuote } from './marketData';

type Listener = (symbol: string, price: number, change24h: number | null) => void;

const BINANCE_SYMBOLS: Record<string, string> = {
  ETH: 'ETHUSDT',
  MATIC: 'MATICUSDT',
  SOL: 'SOLUSDT',
  APT: 'APTUSDT',
  USDC: 'USDCUSDT',
  DAI: 'DAIUSDT',
  BNB: 'BNBUSDT',
  AVAX: 'AVAXUSDT',
  TRX: 'TRXUSDT',
  XLM: 'XLMUSDT',
};

// Reverse map for quick lookup from Binance stream symbol to VeilPay symbol
const STREAM_TO_SYMBOL: Record<string, string> = Object.entries(BINANCE_SYMBOLS).reduce(
  (acc, [internal, binance]) => {
    acc[binance.toLowerCase()] = internal;
    return acc;
  },
  {} as Record<string, string>
);

class MarketStreamer {
  private ws: WebSocket | null = null;
  private reconnectAttempts = 0;
  private maxReconnectAttempts = 5;
  private activeStreams = new Set<string>();

  // Ref count: how many screens are asking for a specific VeilPay symbol
  private refCounts: Record<string, number> = {};

  private listeners: Set<Listener> = new Set();
  private reconnectTimeoutId: NodeJS.Timeout | null = null;

  private connect() {
    if (this.ws && (this.ws.readyState === WebSocket.CONNECTING || this.ws.readyState === WebSocket.OPEN)) {
      return;
    }

    if (this.activeStreams.size === 0) {
      return;
    }

    const streams = Array.from(this.activeStreams).map(s => `${s}@ticker`).join('/');
    const url = `wss://stream.binance.com:9443/stream?streams=${streams}`;

    this.ws = new WebSocket(url);

    this.ws.onopen = () => {
      this.reconnectAttempts = 0;
    };

    this.ws.onmessage = (event) => {
      try {
        const data = JSON.parse(event.data);
        if (data && data.data && data.data.s && data.data.c) {
          const binanceSymbol = data.data.s.toLowerCase();
          const internalSymbol = STREAM_TO_SYMBOL[binanceSymbol];

          if (internalSymbol) {
            const price = parseFloat(data.data.c);
            const change24h = parseFloat(data.data.P);

            // Update the central memory cache
            updateLiveQuote(internalSymbol, price, change24h);

            // Notify active hooks
            this.listeners.forEach(listener => listener(internalSymbol, price, change24h));
          }
        }
      } catch (err) {}
    };

    this.ws.onclose = () => {
      this.ws = null;
      this.attemptReconnect();
    };

    this.ws.onerror = () => {
      // close event will fire next and handle reconnect
    };
  }

  private attemptReconnect() {
    if (this.reconnectAttempts >= this.maxReconnectAttempts || this.activeStreams.size === 0) {
      return;
    }

    const delay = Math.min(1000 * Math.pow(2, this.reconnectAttempts), 30000);
    this.reconnectAttempts++;

    if (this.reconnectTimeoutId) clearTimeout(this.reconnectTimeoutId);
    this.reconnectTimeoutId = setTimeout(() => this.connect(), delay);
  }

  private rebuildConnection() {
    if (this.ws) {
      this.ws.close(); // Will trigger reconnect with new streams
    } else {
      this.connect();
    }
  }

  public subscribe(symbols: readonly string[]) {
    let changed = false;

    symbols.forEach(symbol => {
      const normalized = symbol.trim().toUpperCase();
      const binanceSym = BINANCE_SYMBOLS[normalized];

      if (binanceSym) {
        this.refCounts[normalized] = (this.refCounts[normalized] || 0) + 1;
        if (this.refCounts[normalized] === 1) {
          this.activeStreams.add(binanceSym.toLowerCase());
          changed = true;
        }
      }
    });

    if (changed) {
      this.rebuildConnection();
    }
  }

  public unsubscribe(symbols: readonly string[]) {
    let changed = false;

    symbols.forEach(symbol => {
      const normalized = symbol.trim().toUpperCase();
      const binanceSym = BINANCE_SYMBOLS[normalized];

      if (binanceSym && this.refCounts[normalized] > 0) {
        this.refCounts[normalized]--;
        if (this.refCounts[normalized] === 0) {
          this.activeStreams.delete(binanceSym.toLowerCase());
          changed = true;
        }
      }
    });

    if (changed) {
      if (this.activeStreams.size === 0 && this.ws) {
        this.ws.close();
      } else if (this.activeStreams.size > 0) {
        this.rebuildConnection();
      }
    }
  }

  public addListener(listener: Listener) {
    this.listeners.add(listener);
  }

  public removeListener(listener: Listener) {
    this.listeners.delete(listener);
  }
}

export const marketStreamer = new MarketStreamer();

/**
 * Veilpay Multi-Chain Signer
 *
 * Implements native transaction signing and broadcasting for non-EVM chains
 * using the same signing closure pattern as secureSigner.ts.
 *
 * SECURITY DESIGN:
 * - Mnemonic is retrieved from SecureStore, used to derive chain-specific keys,
 *   sign and broadcast — all within a single async scope.
 * - No key material is ever returned to the caller.
 * - Derived keys are local to each function's stack frame and eligible for GC.
 *
 * Supported chains:
 * - SVM  (Solana): Ed25519 + @solana/web3.js
 * - MVM  (Aptos):  Ed25519 + REST API transactions
 * - XLM  (Stellar): Ed25519 + Horizon API transactions (needs stellar-sdk)
 */

import { keccak256, stringToBytes, toBytes } from 'viem';
import TweetNacl from 'tweetnacl';
import { Buffer } from 'buffer/';
import { getRpcUrl } from './rpc';
import { captureError, addBreadcrumb } from './sentry';
import { getStoredMnemonic, TransactionError } from './transactions';
import { mnemonicToSeed } from '@scure/bip39';
import { derivePath } from 'ed25519-hd-key';
import type { GasEstimate } from './gasEstimator';
import { withTimeout } from './timing';
import { validateAddress as sharedValidateAddress } from './validation';

// ─── Lazy-loaded module caches ──────────────────────────────────────────────

let solanaWeb3Promise: Promise<typeof import('@solana/web3.js')> | null = null;
let stellarSdkPromise: Promise<typeof import('stellar-sdk')> | null = null;

/** Deduplicate concurrent lazy imports */
function getSolanaWeb3(): Promise<typeof import('@solana/web3.js')> {
  if (!solanaWeb3Promise) {
    solanaWeb3Promise = import('@solana/web3.js');
  }
  return solanaWeb3Promise;
}

function getStellarSdk(): Promise<typeof import('stellar-sdk')> {
  if (!stellarSdkPromise) {
    stellarSdkPromise = import('stellar-sdk');
  }
  return stellarSdkPromise;
}

// ─── Types ───────────────────────────────────────────────────────────────────

export interface ChainSignerParams {
  /** Recipient address (chain-specific format) */
  to: string;
  /** Amount as a human-readable string (e.g. '0.01') */
  value: string;
  /** Optional memo / reference note */
  memo?: string;
}

export interface ChainSignerResult {
  hash: string;
  chainId: string | number;
  gasEstimate: GasEstimate;
}

// ─── Internal ─────────────────────────────────────────────────────────────────

const NATIVE_DECIMALS: Record<string, number> = {
  solana: 9,
  'solana-devnet': 9,
  aptos: 8,
  stellar: 7,
  'stellar-testnet': 7,
};

function getNativeDecimals(chainKey: string): number {
  return NATIVE_DECIMALS[chainKey] ?? 9;
}

function getChainType(chainKey: string): 'svm' | 'mvm' | 'xlm' {
  if (chainKey.startsWith('solana')) return 'svm';
  if (chainKey === 'aptos') return 'mvm';
  if (chainKey.startsWith('stellar')) return 'xlm';
  throw new TransactionError(`Unsupported non-EVM chain: ${chainKey}`, 'UNKNOWN');
}

function isSupportedNonEvmChain(chainKey: string): boolean {
  return ['solana', 'solana-devnet', 'aptos', 'stellar', 'stellar-testnet'].includes(chainKey);
}

// Key derivation is now handled securely inside each chain's specific function
// using genuine cryptographic paths rather than SLIP-0010 hashing.

/**
 * Convert a decimal string to the chain-native atomic unit.
 * Throws if the input contains invalid characters.
 */
function toAtomicUnits(value: string, decimals: number): bigint {
  if (!/^\d+(?:\.\d+)?$/.test(value)) {
    throw new TransactionError(`Invalid amount format: ${value}`, 'UNKNOWN');
  }
  const [whole, frac = ''] = value.split('.');
  const padded = frac.padEnd(decimals, '0').slice(0, decimals);
  return BigInt(whole + padded);
}

// ─── Solana (SVM) ────────────────────────────────────────────────────────────

async function sendSolanaTransaction(
  params: ChainSignerParams,
  chainKey: string,
  mnemonicWords: string[],
  ethPrice?: number
): Promise<ChainSignerResult> {
  const rpcUrl = getRpcUrl(chainKey);
  const { PublicKey, Transaction, SystemProgram, Connection, Keypair } = await getSolanaWeb3();
  const seed = await mnemonicToSeed(mnemonicWords.join(' '));
  const derivedSeed = derivePath("m/44'/501'/0'/0'", Buffer.from(seed).toString('hex')).key;
  const solanaKeypair = Keypair.fromSeed(derivedSeed);

  const connection = new Connection(rpcUrl, 'confirmed');
  const fromKeypair = {
    publicKey: solanaKeypair.publicKey,
    secretKey: solanaKeypair.secretKey,
  };

  const toPublicKey = new PublicKey(params.to);
  const lamports = toAtomicUnits(params.value, getNativeDecimals(chainKey));

  if (lamports <= 0n) {
    throw new TransactionError(`Invalid SOL amount: ${params.value}`, 'UNKNOWN');
  }

  const tx = new Transaction().add(
    SystemProgram.transfer({
      fromPubkey: fromKeypair.publicKey,
      toPubkey: toPublicKey,
      lamports: Number(lamports),
    })
  );

  const { blockhash, lastValidBlockHeight } = await withTimeout(
    connection.getLatestBlockhash('confirmed'),
    10_000
  );

  tx.recentBlockhash = blockhash;
  tx.feePayer = fromKeypair.publicKey;

  // Sign with native Ed25519 keypair
  tx.sign({ publicKey: fromKeypair.publicKey, secretKey: fromKeypair.secretKey });

  const rawTx = tx.serialize();
  const signature = await withTimeout(
    connection.sendRawTransaction(rawTx, { skipPreflight: false, maxRetries: 3 }),
    30_000
  );

  const gasEstimate: GasEstimate = {
    gasLimit: 0n,
    maxFeePerGas: 5000n,
    maxPriorityFeePerGas: 0n,
    gasPrice: 5000n,
    estimatedCostWei: 5000n,
    estimatedCostEth: '0.000005',
    estimatedCostUsd: ethPrice ? (0.000005 * ethPrice).toFixed(4) : null,
    isStale: false,
    fetchedAt: Date.now(),
  };

  return { hash: signature, chainId: chainKey, gasEstimate };
}

// ─── Aptos (MVM) ────────────────────────────────────────────────────────────

async function sendAptosTransaction(
  params: ChainSignerParams,
  chainKey: string,
  mnemonicWords: string[],
  ethPrice?: number
): Promise<ChainSignerResult> {
  const rpcUrl = getRpcUrl(chainKey);
  const toAddress = params.to.toLowerCase();

  // We use ts-sdk dynamically to avoid bloating initial bundle if not used
  const { Ed25519Account } = await import('@aptos-labs/ts-sdk');
  const aptosAccount = Ed25519Account.fromDerivationPath({ 
    path: "m/44'/637'/0'/0'/0'", 
    mnemonic: mnemonicWords.join(' ') 
  });

  const fromAddress = aptosAccount.accountAddress.toString();

  const amountOctas = toAtomicUnits(params.value, getNativeDecimals(chainKey));
  if (amountOctas <= 0n) {
    throw new TransactionError(`Invalid APT amount: ${params.value}`, 'UNKNOWN');
  }

  const { Aptos, AptosConfig } = await import('@aptos-labs/ts-sdk');
  const aptosConfig = new AptosConfig({ fullnode: rpcUrl });
  const aptosClient = new Aptos(aptosConfig);

  const transaction = await aptosClient.transaction.build.simple({
    sender: fromAddress,
    data: {
      function: '0x1::aptos_account::transfer',
      functionArguments: [toAddress, amountOctas]
    }
  });

  const senderAuthenticator = aptosClient.transaction.sign({
    signer: aptosAccount,
    transaction,
  });

  const submitRes = await aptosClient.transaction.submit.simple({
    transaction,
    senderAuthenticator,
  });

  const txHash = submitRes.hash;
  if (!txHash) {
    throw new TransactionError('Aptos transaction missing hash in response', 'UNKNOWN');
  }

  const gasEstimate: GasEstimate = {
    gasLimit: 2000n,
    maxFeePerGas: 100n,
    maxPriorityFeePerGas: 0n,
    gasPrice: 100n,
    estimatedCostWei: 200000n,
    estimatedCostEth: '0.0002',
    estimatedCostUsd: ethPrice ? (0.0002 * ethPrice).toFixed(4) : null,
    isStale: false,
    fetchedAt: Date.now(),
  };

  return { hash: txHash, chainId: chainKey, gasEstimate };
}

// ─── Stellar (XLM) ────────────────────────────────────────────────────────

async function sendStellarTransaction(
  params: ChainSignerParams,
  chainKey: string,
  mnemonicWords: string[],
  ethPrice?: number
): Promise<ChainSignerResult> {
  const { Keypair, TransactionBuilder, Operation, Networks, Asset, Memo, Account, Horizon } = await getStellarSdk();

  const isTestnet = chainKey === 'stellar-testnet';
  const horizonUrl = isTestnet
    ? 'https://horizon-testnet.stellar.org'
    : 'https://horizon.stellar.org';
  const networkPassphrase = isTestnet ? Networks.TESTNET : Networks.PUBLIC;

  const toAddress = params.to;

  const seed = await mnemonicToSeed(mnemonicWords.join(' '));
  const stellarDerivedSeed = derivePath("m/44'/148'/0'", Buffer.from(seed).toString('hex')).key;
  const fromKeypair = Keypair.fromRawEd25519Seed(stellarDerivedSeed as any);
  const fromAddress = fromKeypair.publicKey();

  const amountStroops = toAtomicUnits(params.value, getNativeDecimals(chainKey));
  if (amountStroops <= 0n) {
    throw new TransactionError(`Invalid XLM amount: ${params.value}`, 'UNKNOWN');
  }

  // Use the official Horizon SDK server instance for account lookup and submission
  const server = new Horizon.Server(horizonUrl);

  let accountData;
  try {
    accountData = await withTimeout(server.loadAccount(fromAddress), 10_000);
  } catch (e: any) {
    throw new TransactionError(
      `Stellar account not found or network unreachable: ${e?.message || e}`,
      'NETWORK_ERROR'
    );
  }

  // Check balance
  const nativeBal = accountData.balances.find((b: any) => b.asset_type === 'native');
  const currentBalance = parseFloat((nativeBal as any)?.balance || '0');
  const sendAmount = parseFloat(params.value);
  // Reserve 1 XLM for minimum balance + fee
  if (currentBalance < sendAmount + 1) {
    throw new TransactionError(
      `Insufficient funds. Need ${sendAmount + 1} XLM (including reserve), have ${currentBalance} XLM.`,
      'INSUFFICIENT_FUNDS'
    );
  }

  const txBuilder = new TransactionBuilder(accountData, {
    fee: '100000',
    networkPassphrase,
  }).addOperation(
    Operation.payment({
      destination: toAddress,
      asset: Asset.native(),
      amount: params.value,
    })
  );

  if (params.memo) {
    txBuilder.addMemo(Memo.text(params.memo));
  }

  const tx = txBuilder.setTimeout(30).build();
  tx.sign(fromKeypair);

  // Submit using the official SDK — this handles XDR encoding and error parsing correctly
  let submitResult: any;
  try {
    submitResult = await withTimeout(server.submitTransaction(tx), 20_000);
  } catch (e: any) {
    // Horizon errors contain a structured response
    const horizonError = e?.response?.data?.extras?.result_codes;
    const detail = horizonError
      ? JSON.stringify(horizonError)
      : e?.message || 'Unknown Horizon submission error';
    throw new TransactionError(`Stellar send failed: ${detail}`, 'NETWORK_ERROR');
  }

  const txHash = submitResult?.hash;
  if (!txHash) {
    throw new TransactionError('Stellar transaction missing hash in response', 'UNKNOWN');
  }

  const gasEstimate: GasEstimate = {
    gasLimit: 0n,
    maxFeePerGas: 100000n,
    maxPriorityFeePerGas: 0n,
    gasPrice: 100000n,
    estimatedCostWei: 100000n,
    estimatedCostEth: '0.00001',
    estimatedCostUsd: ethPrice ? (0.00001 * ethPrice).toFixed(4) : null,
    isStale: false,
    fetchedAt: Date.now(),
  };

  return { hash: txHash, chainId: isTestnet ? 'stellar-testnet' : 'stellar-mainnet', gasEstimate };
}


// ─── Public API ─────────────────────────────────────────────────────────────

/** Checks if a chain is a non-EVM chain that this signer supports. */
export function isNonEvmChain(chainKey: string): boolean {
  return isSupportedNonEvmChain(chainKey);
}

/**
 * Signs and broadcasts a transaction on a non-EVM chain.
 *
 * @param params    - Transaction parameters (to, value, memo)
 * @param chainKey  - Chain to send on (e.g. 'solana', 'aptos', 'stellar')
 * @param ethPrice  - Current ETH price for USD gas estimate (optional)
 * @throws TransactionError on validation, signing, or broadcast failure
 */
export async function signAndSendNonEvmTransaction(
  params: ChainSignerParams,
  chainKey: string,
  ethPrice?: number
): Promise<ChainSignerResult> {
  addBreadcrumb('Non-EVM transaction signing initiated', 'transaction', { chain: chainKey });

  const chainType = getChainType(chainKey);

  if (!sharedValidateAddress(params.to, chainType)) {
    const chainLabel = chainType === 'svm' ? 'Solana' : chainType === 'mvm' ? 'Aptos' : 'Stellar';
    throw new TransactionError(`Invalid ${chainLabel} address: ${params.to}`, 'INVALID_ADDRESS');
  }

  const mnemonicWords = await getStoredMnemonic();
  if (!mnemonicWords || mnemonicWords.length === 0) {
    throw new TransactionError('No wallet found. Please create or import a wallet first.', 'UNKNOWN');
  }

  try {
    switch (chainType) {
      case 'svm':
        return await sendSolanaTransaction(params, chainKey, mnemonicWords, ethPrice);
      case 'mvm':
        return await sendAptosTransaction(params, chainKey, mnemonicWords, ethPrice);
      case 'xlm':
        return await sendStellarTransaction(params, chainKey, mnemonicWords, ethPrice);
    }
  } catch (error) {
    if (error instanceof TransactionError) throw error;
    const message = (error as any)?.message || `Unknown ${chainType} signing error`;
    captureError(new Error(message), { scope: 'multi-chain-signer', chain: chainKey });
    throw new TransactionError(message, 'UNKNOWN');
  }
}

/**
