import AsyncStorage from '@react-native-async-storage/async-storage';
import { sleep } from './timing';
import { formatFiat, type FiatCurrency } from './transak';

// Cache keys prefix
const CACHE_KEY_PREFIX = '@veilpay_price_';

// Cache duration in milliseconds (5 minutes)
const CACHE_DURATION = 5 * 60 * 1000;

// Fallback prices if API fails and no cache available
export const FALLBACK_PRICES: Record<string, number> = {
  ETH: 3200,
  XLM: 0.11,
  SOL: 145,
  BNB: 580,
  MATIC: 0.72,
  APT: 9.50,
};

// Fallback fiat exchange rates (USD -> FIAT)
const FALLBACK_FIAT_RATES: Record<string, number> = {
  USD: 1.0,
  EUR: 0.92,
  GBP: 0.79,
  INR: 83.5,
};

// API endpoints
const getBinanceUrl = (symbol: string) => `https://api.binance.com/api/v3/ticker/24hr?symbol=${symbol.toUpperCase()}USDT`;
const getCoinCapUrl = (id: string) => `https://api.coincap.io/v2/assets/${id.toLowerCase()}`;

// Map symbols to CoinCap IDs
const SYMBOL_TO_COINCAP_ID: Record<string, string> = {
  ETH: 'ethereum',
  XLM: 'stellar',
  SOL: 'solana',
  BNB: 'binance-coin',
  MATIC: 'polygon',
  APT: 'aptos',
};

export interface PriceData {
  price: number;
  lastUpdated: number;
  source: 'binance' | 'coincap' | 'cache' | 'fallback';
  isStale: boolean;
  change24h?: number | null;
}

export interface PriceFeedResult {
  price: number;
  isLoading: boolean;
  error: string | null;
  lastUpdated: Date | null;
  source: string;
  isStale: boolean;
}

/** Binance API retry config */
const BINANCE_MAX_RETRIES = 2;
const BINANCE_RETRY_BASE_DELAY_MS = 1000;

/**
 * Fetch price from Binance API
 */
async function fetchFromBinance(symbol: string): Promise<{ price: number; change24h: number | null; source: 'binance' }> {
  const url = getBinanceUrl(symbol);

  for (let attempt = 0; attempt <= BINANCE_MAX_RETRIES; attempt++) {
    try {
      const response = await fetch(url, {
        method: 'GET',
        headers: { 'Accept': 'application/json' },
      });

      if (response.ok) {
        const data = await response.json();
        if (!data?.lastPrice) throw new Error('Invalid Binance response format');

        return {
          price: parseFloat(data.lastPrice),
          change24h: typeof data.priceChangePercent === 'string' ? parseFloat(data.priceChangePercent) : null,
          source: 'binance',
        };
      }

      if (response.status === 429 && attempt < BINANCE_MAX_RETRIES) {
        const delayMs = BINANCE_RETRY_BASE_DELAY_MS * Math.pow(2, attempt);
        await sleep(delayMs);
        continue;
      }

      throw new Error(`Binance API error: ${response.status}`);
    } catch (error) {
      if (attempt === BINANCE_MAX_RETRIES) throw error;
      const delayMs = BINANCE_RETRY_BASE_DELAY_MS * Math.pow(2, attempt);
      await sleep(delayMs);
    }
  }
  throw new Error(`Binance API error: Data not received after retries`);
}

/**
 * Fetch price from CoinCap API
 */
async function fetchFromCoinCap(symbol: string): Promise<{ price: number; change24h: number | null; source: 'coincap' }> {
  const id = SYMBOL_TO_COINCAP_ID[symbol.toUpperCase()];
  if (!id) throw new Error(`No CoinCap ID for symbol ${symbol}`);

  const response = await fetch(getCoinCapUrl(id), {
    method: 'GET',
    headers: { 'Accept': 'application/json' },
  });

  if (!response.ok) throw new Error(`CoinCap API error: ${response.status}`);

  const data = await response.json();
  if (!data?.data?.priceUsd) throw new Error('Invalid CoinCap response format');

  return {
    price: parseFloat(data.data.priceUsd),
    change24h: typeof data.data.changePercent24Hr === 'string' ? parseFloat(data.data.changePercent24Hr) : null,
    source: 'coincap',
  };
}

/**
 * Cache management
 */
async function getCachedPrice(symbol: string): Promise<{ price: number; timestamp: number } | null> {
  try {
    const [price, timestamp] = await Promise.all([
      AsyncStorage.getItem(`${CACHE_KEY_PREFIX}${symbol}_price`),
      AsyncStorage.getItem(`${CACHE_KEY_PREFIX}${symbol}_timestamp`),
    ]);
    if (price && timestamp) return { price: parseFloat(price), timestamp: parseInt(timestamp, 10) };
  } catch (e) {}
  return null;
}

async function cachePrice(symbol: string, price: number): Promise<void> {
  try {
    await Promise.all([
      AsyncStorage.setItem(`${CACHE_KEY_PREFIX}${symbol}_price`, price.toString()),
      AsyncStorage.setItem(`${CACHE_KEY_PREFIX}${symbol}_timestamp`, Date.now().toString()),
    ]);
  } catch (e) {}
}

/**
 * Get price for a specific token symbol
 */
export async function getTokenPrice(symbol: string): Promise<PriceData> {
  const normalizedSymbol = symbol.toUpperCase();
  const cached = await getCachedPrice(normalizedSymbol);

  // Try Binance
  try {
    const result = await fetchFromBinance(normalizedSymbol);
    await cachePrice(normalizedSymbol, result.price);
    return {
      price: result.price,
      lastUpdated: Date.now(),
      source: 'binance',
      isStale: false,
      change24h: result.change24h,
    };
  } catch (e) {}

  // Try CoinCap
  try {
    const result = await fetchFromCoinCap(normalizedSymbol);
    await cachePrice(normalizedSymbol, result.price);
    return {
      price: result.price,
      lastUpdated: Date.now(),
      source: 'coincap',
      isStale: false,
      change24h: result.change24h,
    };
  } catch (e) {}

  // Use Cache
  if (cached) {
    return {
      price: cached.price,
      lastUpdated: cached.timestamp,
      source: 'cache',
      isStale: Date.now() - cached.timestamp > CACHE_DURATION,
      change24h: null,
    };
  }

  // Fallback
  return {
    price: FALLBACK_PRICES[normalizedSymbol] || 1.0,
    lastUpdated: Date.now(),
    source: 'fallback',
    isStale: true,
    change24h: null,
  };
}

/** Compatibility wrapper for legacy code */
export const getETHPrice = () => getTokenPrice('ETH');
export const FALLBACK_ETH_PRICE = FALLBACK_PRICES.ETH;

export async function getFiatExchangeRate(currency: string): Promise<number> {
  if (currency === 'USD') return 1.0;

  try {
    const cached = await AsyncStorage.getItem(`${CACHE_KEY_PREFIX}fiat_${currency}`);
    if (cached) {
      const { rate, timestamp } = JSON.parse(cached);
      if (Date.now() - timestamp < CACHE_DURATION * 12) {
        return rate;
      }
    }
  } catch (e) {}

  try {
    const coincapIdMap: Record<string, string> = {
      EUR: 'euro',
      GBP: 'british-pound-sterling',
      INR: 'indian-rupee'
    };

    const id = coincapIdMap[currency];
    if (id) {
      const response = await fetch(`https://api.coincap.io/v2/rates/${id}`);
      if (response.ok) {
        const data = await response.json();
        if (data?.data?.rateUsd) {
          const rate = 1 / parseFloat(data.data.rateUsd);
          await AsyncStorage.setItem(`${CACHE_KEY_PREFIX}fiat_${currency}`, JSON.stringify({ rate, timestamp: Date.now() }));
          return rate;
        }
      }
    }
  } catch (e) {}

  return FALLBACK_FIAT_RATES[currency] || 1.0;
}

export async function convertTokenToUsd(amount: number | string, symbol: string): Promise<{
  usdValue: number;
  price: number;
  priceData: PriceData;
}> {
  const priceData = await getTokenPrice(symbol);
  const amountNum = typeof amount === 'string' ? parseFloat(amount) : amount;
  return {
    usdValue: amountNum * priceData.price,
    price: priceData.price,
    priceData,
  };
}

export function formatUsdValue(usdValue: number): string {
  return `$${usdValue.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
}

export function formatFiatValue(usdValue: number, currencyCode: string = 'USD'): string {
  if (currencyCode === 'USD') return formatUsdValue(usdValue);

  // Use transak's formatFiat to properly format other currencies
  try {
    return formatFiat(usdValue, currencyCode as FiatCurrency);
  } catch (e) {
    // Fallback if Intl fails
    return `${usdValue.toFixed(2)} ${currencyCode}`;
  }
}

export function formatLastUpdated(timestamp: number): string {
  const diff = Date.now() - timestamp;
  if (diff < 60000) return 'just now';
  if (diff < 3600000) return `${Math.floor(diff / 60000)}m ago`;
  return `${Math.floor(diff / 3600000)}h ago`;
}

export default {
  getTokenPrice,
  getETHPrice,
  getFiatExchangeRate,
  convertTokenToUsd,
  formatUsdValue,
  formatFiatValue,
  formatLastUpdated,
  FALLBACK_PRICES,
};

import { formatEther } from 'viem';
import { Connection, PublicKey } from '@solana/web3.js';
import type { TransactionRecord } from '../types/transactions';
import { captureError } from './sentry';

const REQUEST_TIMEOUT_MS = 10000;

export async function fetchEvmHistory(
  address: string,
  chainKey: string,
  cursor: string | undefined,
  limit: number
): Promise<{ transactions: TransactionRecord[]; nextCursor: string | null; hasMore: boolean }> {
  // Map chainKey to Etherscan V2 API
  const apiMap: Record<string, string> = {
    ethereum: 'https://api.etherscan.io/v2/api?chainid=1',
    polygon: 'https://api.etherscan.io/v2/api?chainid=137',
    arbitrum: 'https://api.etherscan.io/v2/api?chainid=42161',
    sepolia: 'https://api.etherscan.io/v2/api?chainid=11155111',
  };

  const apiKeyMap: Record<string, string | undefined> = {
    ethereum: process.env.EXPO_PUBLIC_ETHERSCAN_API_KEY,
    polygon: process.env.EXPO_PUBLIC_ETHERSCAN_API_KEY, // V2 uses Etherscan key for all
    arbitrum: process.env.EXPO_PUBLIC_ETHERSCAN_API_KEY,
    sepolia: process.env.EXPO_PUBLIC_ETHERSCAN_API_KEY,
  };

  const baseUrl = apiMap[chainKey];
  if (!baseUrl) {
    throw new Error(`Unsupported EVM chain for public indexer: ${chainKey}`);
  }

  const apiKey = apiKeyMap[chainKey] || '';
  const page = cursor ? parseInt(cursor, 10) : 1;
  const offset = limit;

  let url = `${baseUrl}&module=account&action=txlist&address=${address}&startblock=0&endblock=99999999&page=${page}&offset=${offset}&sort=desc`;
  if (apiKey) {
    url += `&apikey=${apiKey}`;
  }

  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), REQUEST_TIMEOUT_MS);

  try {
    const response = await fetch(url, { signal: controller.signal });
    const data = await response.json();

    if (data.status === '0' && data.message !== 'No transactions found') {
      throw new Error(`Etherscan API error: ${data.result}`);
    }

    const rawTxs = Array.isArray(data.result) ? data.result : [];

    const transactions: TransactionRecord[] = rawTxs.map((tx: any) => {
      const isSender = tx.from.toLowerCase() === address.toLowerCase();
      return {
        id: tx.hash,
        type: isSender ? 'sent' : 'received',
        amount: formatEther(BigInt(tx.value || '0')),
        token: 'Ether', // Can be expanded for ERC20 via tokentx action
        tokenSymbol: 'ETH',
        from: tx.from,
        to: tx.to,
        timestamp: parseInt(tx.timeStamp, 10) * 1000,
        status: tx.isError === '0' ? 'completed' : 'failed',
        hash: tx.hash,
        network: chainKey,
        fee: formatEther(BigInt(tx.gasUsed || '0') * BigInt(tx.gasPrice || '0')),
      };
    });

    const hasMore = rawTxs.length === limit;
    const nextCursor = hasMore ? (page + 1).toString() : null;

    return { transactions, nextCursor, hasMore };
  } catch (error) {
    const isAbort = error instanceof Error && error.name === 'AbortError';
    if (!isAbort) {
      captureError(error instanceof Error ? error : new Error('EVM Indexer failed'), { chain: chainKey });
    }
    return { transactions: [], nextCursor: null, hasMore: false };
  } finally {
    clearTimeout(timeoutId);
  }
}

export async function fetchSolanaHistory(
  address: string,
  chainKey: string,
  cursor: string | undefined,
  limit: number
): Promise<{ transactions: TransactionRecord[]; nextCursor: string | null; hasMore: boolean }> {
  try {
    const rpcUrl = chainKey === 'solana' 
      ? (process.env.EXPO_PUBLIC_SOLANA_RPC_URL || 'https://api.mainnet-beta.solana.com')
      : (process.env.EXPO_PUBLIC_SOLANA_DEVNET_RPC_URL || 'https://api.devnet.solana.com');

    const connection = new Connection(rpcUrl);
    const pubKey = new PublicKey(address);

    // Fetch signatures
    const signatures = await connection.getSignaturesForAddress(pubKey, {
      before: cursor,
      limit,
    });

    if (signatures.length === 0) {
      return { transactions: [], nextCursor: null, hasMore: false };
    }

    // Parse transactions
    const parsedTxs = await connection.getParsedTransactions(
      signatures.map((s) => s.signature),
      { maxSupportedTransactionVersion: 0 }
    );

    const transactions: TransactionRecord[] = [];

    parsedTxs.forEach((tx, idx) => {
      if (!tx || !tx.meta || !tx.transaction) return;
      const signature = signatures[idx].signature;
      const blockTime = tx.blockTime ? tx.blockTime * 1000 : Date.now();

      // Calculate native balance change for the address
      const accountIndex = tx.transaction.message.accountKeys.findIndex(
        (k) => k.pubkey.toBase58() === address
      );

      if (accountIndex === -1) return;

      const preBalance = tx.meta.preBalances[accountIndex];
      const postBalance = tx.meta.postBalances[accountIndex];
      const change = postBalance - preBalance;

      // If change is negative, we sent. If positive, we received.
      const isSender = change < 0;
      const amountAbs = Math.abs(change);

      // Rough approximation of to/from since Solana uses many accounts
      const from = isSender ? address : (tx.transaction.message.accountKeys[0]?.pubkey.toBase58() || 'unknown');
      const to = isSender ? (tx.transaction.message.accountKeys[1]?.pubkey.toBase58() || 'unknown') : address;

      transactions.push({
        id: signature,
        type: isSender ? 'sent' : 'received',
        amount: (amountAbs / 1e9).toString(), // lamports to SOL
        token: 'Solana',
        tokenSymbol: 'SOL',
        from,
        to,
        timestamp: blockTime,
        status: tx.meta.err ? 'failed' : 'completed',
        hash: signature,
        network: chainKey,
        fee: (tx.meta.fee / 1e9).toString(),
      });
    });

    const hasMore = signatures.length === limit;
    const nextCursor = hasMore ? signatures[signatures.length - 1].signature : null;

    return { transactions, nextCursor, hasMore };
  } catch (error) {
    const isAbort = error instanceof Error && error.name === 'AbortError';
    if (!isAbort) {
      captureError(error instanceof Error ? error : new Error('Solana Indexer failed'), { chain: chainKey });
    }
    return { transactions: [], nextCursor: null, hasMore: false };
  }
}

export async function fetchStellarHistory(
  address: string,
  chainKey: string,
  cursor: string | undefined,
  limit: number
): Promise<{ transactions: TransactionRecord[]; nextCursor: string | null; hasMore: boolean }> {
  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), REQUEST_TIMEOUT_MS);

  try {
    const horizonUrl = chainKey === 'stellar'
      ? 'https://horizon.stellar.org'
      : 'https://horizon-testnet.stellar.org';

    // Use /operations endpoint — covers payments AND create_account ops
    let url = `${horizonUrl}/accounts/${address}/operations?limit=${limit}&order=desc`;
    if (cursor) {
      url += `&cursor=${cursor}`;
    }

    const response = await fetch(url, { signal: controller.signal });
    if (!response.ok) {
      if (response.status === 404) {
        // Account not funded yet — not an error
        return { transactions: [], nextCursor: null, hasMore: false };
      }
      throw new Error(`Horizon API error: ${response.status}`);
    }

    const data = await response.json();
    const records: any[] = data._embedded?.records || [];

    const transactions: TransactionRecord[] = records
      .map((record: any): TransactionRecord | null => {
        const opType: string = record.type || '';

        let from = '';
        let to = '';
        let amount = '0';
        let tokenSymbol = 'XLM';
        let tokenName = 'Stellar';

        if (opType === 'payment') {
          from = record.from || '';
          to = record.to || '';
          amount = record.amount || '0';
          const isNative = record.asset_type === 'native';
          tokenSymbol = isNative ? 'XLM' : (record.asset_code || 'XLM');
          tokenName = isNative ? 'Stellar' : tokenSymbol;
        } else if (opType === 'create_account') {
          from = record.funder || '';
          to = record.account || '';
          amount = record.starting_balance || '0';
        } else {
          // Skip unsupported operation types (path_payment, change_trust, etc.)
          return null;
        }

        const isSender = from.toLowerCase() === address.toLowerCase();

        return {
          id: record.id,
          type: isSender ? 'sent' : 'received',
          amount,
          token: tokenName,
          tokenSymbol,
          from: from || 'unknown',
          to: to || 'unknown',
          timestamp: new Date(record.created_at).getTime(),
          // operations endpoint doesn't have transaction_successful — check transaction_hash existence
          status: record.transaction_hash ? 'completed' : 'pending',
          hash: record.transaction_hash || record.id,
          network: chainKey,
        };
      })
      .filter((tx): tx is TransactionRecord => tx !== null);

    const hasMore = records.length === limit;
    const nextCursor = hasMore ? records[records.length - 1].paging_token : null;

    return { transactions, nextCursor, hasMore };
  } catch (error) {
    const isAbort = error instanceof Error && error.name === 'AbortError';
    if (!isAbort) {
      captureError(error instanceof Error ? error : new Error('Stellar Indexer failed'), { chain: chainKey });
    }
    return { transactions: [], nextCursor: null, hasMore: false };
  } finally {
    clearTimeout(timeoutId);
  }
}

import { createPublicClient, http, PublicClient } from 'viem';
import { captureError } from './sentry';

type RpcProviderStatus = 'healthy' | 'degraded' | 'open';

interface RpcEndpoint {
  name: string;
  url: string;
  weight: number;
}

interface CircuitBreakerState {
  status: RpcProviderStatus;
  failureCount: number;
  lastFailureAt: number;
  openUntil: number;
}

const CIRCUIT_OPEN_THRESHOLD = 3;
const CIRCUIT_RESET_MS = 30_000;
const REQUEST_TIMEOUT_MS = 5_000;
const HEALTH_CHECK_INTERVAL_MS = 60_000;
const MAX_RETRIES = 3;
const RETRY_BASE_DELAY_MS = 300;

function buildEndpoints(chainKey: string): RpcEndpoint[] {
  const alchemyKey = process.env.EXPO_PUBLIC_ALCHEMY_API_KEY?.trim();
  const infuraKey = process.env.EXPO_PUBLIC_INFURA_API_KEY?.trim();

  const alchemyNetworks: Record<string, string> = {
    ethereum: 'eth-mainnet',
    polygon: 'polygon-mainnet',
    arbitrum: 'arb-mainnet',
    base: 'base-mainnet',
    sepolia: 'eth-sepolia',
    solana: 'solana-mainnet',
  };

  const infuraNetworks: Record<string, string> = {
    ethereum: 'mainnet',
    polygon: 'polygon-mainnet',
    arbitrum: 'arbitrum-mainnet',
    base: 'base-mainnet',
    sepolia: 'sepolia',
  };

  const publicFallbacks: Record<string, string> = {
    ethereum: 'https://ethereum-rpc.publicnode.com',
    polygon: 'https://polygon-rpc.com',
    arbitrum: 'https://arb1.arbitrum.io/rpc',
    base: 'https://mainnet.base.org',
    sepolia: 'https://rpc.sepolia.org',
    solana: 'https://api.mainnet-beta.solana.com',
    'solana-devnet': 'https://api.devnet.solana.com',
    aptos: 'https://fullnode.mainnet.aptoslabs.com',
  };

  const overrideEnvKey = `EXPO_PUBLIC_RPC_${chainKey.replace(/-/g, '_').toUpperCase()}`;
  const overrideUrl = (process.env[overrideEnvKey] || '').trim();

  const endpoints: RpcEndpoint[] = [];

  if (overrideUrl) {
    endpoints.push({ name: `override-${chainKey}`, url: overrideUrl, weight: 10 });
    return endpoints;
  }

  const alchemyNetwork = alchemyNetworks[chainKey];
  if (alchemyKey && alchemyNetwork) {
    const url = chainKey === 'solana'
      ? `https://solana-mainnet.g.alchemy.com/v2/${alchemyKey}`
      : `https://${alchemyNetwork}.g.alchemy.com/v2/${alchemyKey}`;
    endpoints.push({ name: `alchemy-${chainKey}`, url, weight: 3 });
  }

  const infuraNetwork = infuraNetworks[chainKey];
  if (infuraKey && infuraNetwork) {
    endpoints.push({
      name: `infura-${chainKey}`,
      url: `https://${infuraNetwork}.infura.io/v3/${infuraKey}`,
      weight: 2,
    });
  }

  const publicUrl = publicFallbacks[chainKey];
  if (publicUrl) {
    endpoints.push({ name: `public-${chainKey}`, url: publicUrl, weight: 1 });
  }

  return endpoints;
}

const circuitState = new Map<string, CircuitBreakerState>();

function getCircuit(key: string): CircuitBreakerState {
  if (!circuitState.has(key)) {
    circuitState.set(key, {
      status: 'healthy',
      failureCount: 0,
      lastFailureAt: 0,
      openUntil: 0,
    });
  }
  return circuitState.get(key)!;
}

function isCircuitOpen(endpointName: string): boolean {
  const state = getCircuit(endpointName);
  if (state.status !== 'open') return false;
  if (Date.now() >= state.openUntil) {
    state.status = 'degraded';
    return false;
  }
  return true;
}

function recordSuccess(endpointName: string): void {
  const state = getCircuit(endpointName);
  state.status = 'healthy';
  state.failureCount = 0;
}

function recordFailure(endpointName: string): void {
  const state = getCircuit(endpointName);
  state.failureCount += 1;
  state.lastFailureAt = Date.now();

  if (state.failureCount >= CIRCUIT_OPEN_THRESHOLD) {
    state.status = 'open';
    state.openUntil = Date.now() + CIRCUIT_RESET_MS;
    console.warn(`[rpcPool] Circuit OPEN for ${endpointName} — cooldown 30s`);
  } else {
    state.status = 'degraded';
  }
}

class RpcProviderPool {
  private readonly chainKey: string;
  private endpoints: RpcEndpoint[];
  private providers = new Map<string, PublicClient>();
  private healthTimer: ReturnType<typeof setInterval> | null = null;

  constructor(chainKey: string) {
    this.chainKey = chainKey;
    this.endpoints = buildEndpoints(chainKey);

    if (this.endpoints.length === 0) {
      console.warn(`[rpcPool] No endpoints configured for chain: ${chainKey}`);
    }

    this.startHealthChecks();
  }

  getProvider(): PublicClient {
    const available = this.endpoints
      .filter((ep) => !isCircuitOpen(ep.name))
      .sort((a, b) => b.weight - a.weight);

    if (available.length === 0) {
      const err = new Error(`[rpcPool] All providers circuit-open for chain: ${this.chainKey}`);
      captureError(err, { scope: 'rpc-pool', chain: this.chainKey });
      throw err;
    }

    const chosen = available[0];
    return this.getOrCreateProvider(chosen);
  }

  async call<T>(fn: (provider: PublicClient) => Promise<T>): Promise<T> {
    const available = this.endpoints
      .filter((ep) => !isCircuitOpen(ep.name))
      .sort((a, b) => b.weight - a.weight);

    if (available.length === 0) {
      throw new Error(`[rpcPool] No available providers for: ${this.chainKey}`);
    }

    let lastError: unknown;

    for (const endpoint of available) {
      const provider = this.getOrCreateProvider(endpoint);

      for (let attempt = 0; attempt < MAX_RETRIES; attempt++) {
        try {
          const result = await this.withTimeout(fn(provider));
          recordSuccess(endpoint.name);
          return result;
        } catch (err) {
          lastError = err;
          recordFailure(endpoint.name);

          if (attempt < MAX_RETRIES - 1) {
            const delay = RETRY_BASE_DELAY_MS * Math.pow(2, attempt);
            await sleep(delay);
          }

          if (isCircuitOpen(endpoint.name)) break;
        }
      }
    }

    const finalErr = lastError instanceof Error
      ? lastError
      : new Error(`[rpcPool] All providers failed for: ${this.chainKey}`);
    captureError(finalErr, { scope: 'rpc-pool', chain: this.chainKey });
    throw finalErr;
  }

  private startHealthChecks(): void {
    if (typeof setInterval === 'undefined') return;

    this.healthTimer = setInterval(() => {
      void this.runHealthChecks();
    }, HEALTH_CHECK_INTERVAL_MS);
  }

  private async runHealthChecks(): Promise<void> {
    for (const endpoint of this.endpoints) {
      const state = getCircuit(endpoint.name);
      if (state.status !== 'open' && Date.now() < state.openUntil) continue;
      const provider = this.getOrCreateProvider(endpoint);
      try {
        await this.withTimeout(provider.getBlockNumber());
        recordSuccess(endpoint.name);
        console.log(`[rpcPool] Health check passed: ${endpoint.name}`);
      } catch {
        console.warn(`[rpcPool] Health check failed: ${endpoint.name}`);
      }
    }
  }

  private getOrCreateProvider(endpoint: RpcEndpoint): PublicClient {
    if (!this.providers.has(endpoint.name)) {
      this.providers.set(
        endpoint.name,
        createPublicClient({ transport: http(endpoint.url) })
      );
    }
    return this.providers.get(endpoint.name)!;
  }

  private withTimeout<T>(promise: Promise<T>): Promise<T> {
    return Promise.race([
      promise,
      new Promise<T>((_, reject) =>
        setTimeout(() => reject(new Error(`RPC timeout after ${REQUEST_TIMEOUT_MS}ms`)), REQUEST_TIMEOUT_MS)
      ),
    ]);
  }

  destroy(): void {
    if (this.healthTimer) {
      clearInterval(this.healthTimer);
      this.healthTimer = null;
    }
    this.providers.clear();
  }
}

const pools = new Map<string, RpcProviderPool>();

export function getPool(chainKey: string): RpcProviderPool {
  if (!pools.has(chainKey)) {
    pools.set(chainKey, new RpcProviderPool(chainKey));
  }
  return pools.get(chainKey)!;
}

export function getPoolProvider(chainKey: string): PublicClient {
  return getPool(chainKey).getProvider();
}

export function poolCall<T>(
  chainKey: string,
  fn: (provider: PublicClient) => Promise<T>
): Promise<T> {
  return getPool(chainKey).call(fn);
}

export function getPoolStatus(chainKey: string): Record<string, CircuitBreakerState> {
  const pool = pools.get(chainKey);
  if (!pool) return {};
  const endpoints = buildEndpoints(chainKey);
  const result: Record<string, CircuitBreakerState> = {};
  for (const ep of endpoints) {
    result[ep.name] = getCircuit(ep.name);
  }
  return result;
}

export function destroyAllPools(): void {
  for (const pool of pools.values()) {
    pool.destroy();
  }
  pools.clear();
}

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

