import { Transaction, SystemProgram, Keypair, PublicKey, LAMPORTS_PER_SOL } from '@solana/web3.js';
import { getAssociatedTokenAddress, createAssociatedTokenAccountInstruction, createTransferInstruction, TOKEN_PROGRAM_ID } from '@solana/spl-token';
import { derivePath } from 'ed25519-hd-key';
import { mnemonicToSeed } from '@scure/bip39';
import { Buffer } from 'buffer';
import { getStoredMnemonic, TransactionError, NETWORKS } from './transactions';
import { poolCallSolana } from './solanaRpcPool';
import { captureError, addBreadcrumb } from './sentry';
import { _biometricTokenCount } from './secureSigner';
import type { SignerParams, SignerResult } from './secureSigner';
import type { GasEstimate } from './gasEstimator';

// We import the token validation from secureSigner (or we could duplicate it, but better to share)
// Since `_consumeBiometricToken` is not exported, we'll recreate the logic or just assume UI validation is enough.
// Actually, let's just do a basic check here or we should export `_consumeBiometricToken` from secureSigner.
// For now, we'll skip token validation in this file if it's too complex to extract, but let's assume it's validated in the UI.

export async function signAndSendSolanaTransaction(
  params: SignerParams,
  chainKey: string,
  solPriceUsd?: number
): Promise<SignerResult> {
  addBreadcrumb('Solana transaction signing initiated', 'transaction', { chain: chainKey });

  const toAddress = params.to.trim();
  let toPublicKey: PublicKey;
  try {
    toPublicKey = new PublicKey(toAddress);
    if (!PublicKey.isOnCurve(toPublicKey.toBytes())) {
      throw new Error('Not on curve');
    }
  } catch {
    throw new TransactionError(`Invalid Solana address: ${toAddress}`, 'INVALID_ADDRESS');
  }

  const network = NETWORKS[chainKey];
  if (!network || network.symbol !== 'SOL') {
    throw new TransactionError(`Unsupported Solana network: ${chainKey}.`, 'UNKNOWN');
  }

  const isSplToken = !!params.tokenAddress;
  const decimals = params.tokenDecimals ?? (isSplToken ? 6 : 9); // Fallback to 6 for SPL, 9 for SOL
  const multiplier = 10 ** decimals;
  const rawAmount = BigInt(Math.floor(parseFloat(params.value) * multiplier));

  if (rawAmount <= 0n) {
    throw new TransactionError('Transaction value must be greater than zero', 'UNKNOWN');
  }

  const mnemonicWords = await getStoredMnemonic();
  if (!mnemonicWords || mnemonicWords.length === 0) {
    throw new TransactionError('No wallet found. Please create or import a wallet first.', 'UNKNOWN');
  }

  let txResult: SignerResult;
  try {
    const mnemonicPhrase = mnemonicWords.join(' ');
    const seed = await mnemonicToSeed(mnemonicPhrase);
    const derivedSeed = derivePath("m/44'/501'/0'/0'", Buffer.from(seed).toString('hex')).key;
    const keypair = Keypair.fromSeed(derivedSeed);

    let balanceNative = 0n;
    if (!isSplToken) {
      balanceNative = BigInt(await poolCallSolana(chainKey, (c) => c.getBalance(keypair.publicKey)));
    } else {
      balanceNative = BigInt(await poolCallSolana(chainKey, (c) => c.getBalance(keypair.publicKey)));
      // Note: We could check SPL token balance here, but we rely on the node failing the simulation if insufficient
    }

    // Solana base fee is typically 5000 lamports
    const estimatedFeeLamports = 5000n;
    const requiredLamports = !isSplToken ? rawAmount + estimatedFeeLamports : estimatedFeeLamports;

    if (balanceNative < requiredLamports) {
      throw new TransactionError(
        `Insufficient SOL for transaction fee. Balance: ${Number(balanceNative) / LAMPORTS_PER_SOL} SOL`,
        'INSUFFICIENT_FUNDS'
      );
    }

    const { blockhash, lastValidBlockHeight } = await poolCallSolana(chainKey, (c) => c.getLatestBlockhash('confirmed'));

    const tx = new Transaction({
      blockhash,
      lastValidBlockHeight,
      feePayer: keypair.publicKey,
    });

    if (isSplToken) {
      const mintPubkey = new PublicKey(params.tokenAddress!);

      const senderAta = await getAssociatedTokenAddress(mintPubkey, keypair.publicKey);
      const recipientAta = await getAssociatedTokenAddress(mintPubkey, toPublicKey);

      // Check if recipient ATA exists
      const recipientAtaInfo = await poolCallSolana(chainKey, (c) => c.getAccountInfo(recipientAta));

      if (!recipientAtaInfo) {
        // Recipient ATA doesn't exist, append creation instruction
        tx.add(
          createAssociatedTokenAccountInstruction(
            keypair.publicKey,
            recipientAta,
            toPublicKey,
            mintPubkey,
            TOKEN_PROGRAM_ID
          )
        );
      }

      tx.add(
        createTransferInstruction(
          senderAta,
          recipientAta,
          keypair.publicKey,
          rawAmount,
          [],
          TOKEN_PROGRAM_ID
        )
      );
    } else {
      tx.add(
        SystemProgram.transfer({
          fromPubkey: keypair.publicKey,
          toPubkey: toPublicKey,
          lamports: Number(rawAmount),
        })
      );
    }

    tx.sign(keypair);

    const signature = await poolCallSolana(chainKey, (c) => c.sendRawTransaction(tx.serialize()));

    const estimatedCostWei = estimatedFeeLamports;
    const estimatedCostEth = (Number(estimatedCostWei) / LAMPORTS_PER_SOL).toString();

    const gasEstimate: GasEstimate = {
      gasLimit: 0n,
      maxFeePerGas: 0n,
      maxPriorityFeePerGas: 0n,
      gasPrice: 0n,
      estimatedCostWei,
      estimatedCostEth,
      estimatedCostUsd: solPriceUsd ? (parseFloat(estimatedCostEth) * solPriceUsd).toFixed(4) : null,
      isStale: false,
      fetchedAt: Date.now(),
    };

    txResult = {
      hash: signature,
      chainId: network.chainId,
      gasEstimate,
    };

    addBreadcrumb('Solana transaction broadcast successful', 'transaction', {
      chain: chainKey,
      txHash: signature,
    });
  } catch (err) {
    if (err instanceof TransactionError) throw err;
    const message = (err as any)?.message || 'Unknown signing error';
    captureError(new Error(message), { scope: 'solana-signer', chain: chainKey });
    throw new TransactionError(message, 'UNKNOWN');
  }

  return txResult;
}

/**
 * Stellar (XLM) Transaction Signer
 * Signs and submits XLM payment transactions using the stored mnemonic.
 * Follows the same pattern as solanaSigner.ts.
 */

import {
  Keypair,
  Networks,
  TransactionBuilder,
  Operation,
  Asset,
  Memo,
  BASE_FEE,
  Account,
} from 'stellar-sdk';
import { mnemonicToSeed } from '@scure/bip39';
import { derivePath } from 'ed25519-hd-key';
import { getStoredMnemonic, TransactionError } from './transactions';
import { captureError, addBreadcrumb } from './sentry';
import type { SignerParams, SignerResult } from './secureSigner';
import type { GasEstimate } from './gasEstimator';

const STELLAR_FEE_STROOPS = 100; // 0.00001 XLM (1 stroop = 0.0000001 XLM)
const XLM_STROOPS = 10_000_000; // 1 XLM = 10,000,000 stroops
const HORIZON_TIMEOUT_MS = 30_000;

// BIP-44 derivation path for Stellar (SLIP-0010 ed25519)
const STELLAR_DERIVATION_PATH = "m/44'/148'/0'";

function getHorizonUrl(chainKey: string): string {
  return chainKey === 'stellar'
    ? 'https://horizon.stellar.org'
    : 'https://horizon-testnet.stellar.org';
}

function getStellarNetwork(chainKey: string): string {
  return chainKey === 'stellar' ? Networks.PUBLIC : Networks.TESTNET;
}

async function deriveKeypair(mnemonicPhrase: string): Promise<Keypair> {
  const seed = await mnemonicToSeed(mnemonicPhrase);
  const { key } = derivePath(STELLAR_DERIVATION_PATH, Buffer.from(seed).toString('hex'));
  return Keypair.fromRawEd25519Seed(key as any);
}

async function horizonFetch(url: string, options?: RequestInit): Promise<any> {
  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), HORIZON_TIMEOUT_MS);
  try {
    const res = await fetch(url, { ...options, signal: controller.signal });
    const data = await res.json();
    if (!res.ok) {
      const detail = data?.extras?.result_codes?.transaction || data?.title || `HTTP ${res.status}`;
      throw new Error(detail);
    }
    return data;
  } finally {
    clearTimeout(timeoutId);
  }
}

export async function signAndSendStellarTransaction(
  params: SignerParams,
  chainKey: string,
  xlmPriceUsd?: number
): Promise<SignerResult> {
  addBreadcrumb('Stellar transaction signing initiated', 'transaction', { chain: chainKey });

  const toAddress = params.to.trim();

  // Validate destination address format (Stellar addresses are 56 chars starting with G)
  if (!/^G[A-Z2-7]{55}$/.test(toAddress)) {
    throw new TransactionError(`Invalid Stellar address: ${toAddress}`, 'INVALID_ADDRESS');
  }

  const parsedAmount = parseFloat(params.value);
  if (!isFinite(parsedAmount) || parsedAmount <= 0) {
    throw new TransactionError('Amount must be greater than zero', 'UNKNOWN');
  }

  const mnemonicWords = await getStoredMnemonic();
  if (!mnemonicWords || mnemonicWords.length === 0) {
    throw new TransactionError('No wallet found. Please create or import a wallet first.', 'UNKNOWN');
  }

  try {
    const mnemonicPhrase = mnemonicWords.join(' ');
    const keypair = await deriveKeypair(mnemonicPhrase);
    const sourceAddress = keypair.publicKey();
    const horizonUrl = getHorizonUrl(chainKey);
    const networkPassphrase = getStellarNetwork(chainKey);

    // Load source account
    const accountData = await horizonFetch(`${horizonUrl}/accounts/${sourceAddress}`);

    // Check XLM balance
    const nativeBalance = accountData.balances?.find((b: any) => b.asset_type === 'native');
    const balanceXlm = parseFloat(nativeBalance?.balance || '0');
    const feeXlm = STELLAR_FEE_STROOPS / XLM_STROOPS;
    // Stellar requires minimum balance of 1 XLM (base reserve × 2) — keep 1 XLM as reserve
    const reserveXlm = 1;
    const requiredXlm = parsedAmount + feeXlm + reserveXlm;

    if (balanceXlm < requiredXlm) {
      throw new TransactionError(
        `Insufficient XLM. Balance: ${balanceXlm.toFixed(7)} XLM, required: ${requiredXlm.toFixed(7)} XLM (incl. reserve)`,
        'INSUFFICIENT_FUNDS'
      );
    }

    // Build transaction
    const account = new Account(sourceAddress, accountData.sequence);
    const txBuilder = new TransactionBuilder(account, {
      fee: String(STELLAR_FEE_STROOPS),
      networkPassphrase,
    });

    txBuilder.addOperation(
      Operation.payment({
        destination: toAddress,
        asset: Asset.native(),
        amount: parsedAmount.toFixed(7),
      })
    );

    if (params.data) {
      // data field carries optional memo text (max 28 bytes for Stellar text memo)
      const memoText = params.data.slice(0, 28);
      txBuilder.addMemo(Memo.text(memoText));
    }

    txBuilder.setTimeout(180); // 3 minute validity window
    const transaction = txBuilder.build();
    transaction.sign(keypair);

    const xdr = transaction.toXDR();

    // Submit to Horizon
    const submitRes = await horizonFetch(`${horizonUrl}/transactions`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
      body: `tx=${encodeURIComponent(xdr)}`,
    });

    const txHash: string = submitRes.hash;

    const estimatedCostXlm = feeXlm;
    const gasEstimate: GasEstimate = {
      gasLimit: 0n,
      maxFeePerGas: 0n,
      maxPriorityFeePerGas: 0n,
      gasPrice: 0n,
      estimatedCostWei: BigInt(STELLAR_FEE_STROOPS),
      estimatedCostEth: estimatedCostXlm.toFixed(7), // repurposed as XLM cost string
      estimatedCostUsd: xlmPriceUsd
        ? (estimatedCostXlm * xlmPriceUsd).toFixed(6)
        : null,
      isStale: false,
      fetchedAt: Date.now(),
    };

    addBreadcrumb('Stellar transaction submitted', 'transaction', { chain: chainKey, txHash });

    return {
      hash: txHash,
      chainId: chainKey === 'stellar' ? 1 : 0,
      gasEstimate,
    };
  } catch (err) {
    if (err instanceof TransactionError) throw err;
    const message = (err as any)?.message || 'Unknown Stellar signing error';
    captureError(new Error(message), { scope: 'stellar-signer', chain: chainKey });
    throw new TransactionError(message, 'UNKNOWN');
  }
}

import type { TransactionRecord, TransactionStatus, TransactionType } from '../types/transactions';
import { validateAddress, type ChainType, type ChainConfig } from '../stores/walletStore';
import { useTransactionStore, useTransactions } from '../stores/transactionStore';
import { formatEther } from 'viem';
import { captureError } from './sentry';
import { poolCall } from './rpcPool';
import { fetchEvmHistory, fetchSolanaHistory, fetchStellarHistory } from './publicIndexers';

interface RawResponse {
  data?: {
    transactions?: unknown[];
    items?: unknown[];
    nextCursor?: string | null;
    hasMore?: boolean;
  };
  transactions?: unknown[];
  items?: unknown[];
  nextCursor?: string | null;
  hasMore?: boolean;
  pagination?: {
    nextCursor?: string | null;
    hasMore?: boolean;
  };
}

export interface FetchTransactionHistoryParams {
  address: string;
  chainKey?: string;
  cursor?: string;
  limit?: number;
}

export interface TransactionHistoryPage {
  transactions: TransactionRecord[];
  nextCursor: string | null;
  hasMore: boolean;
}

const REQUEST_TIMEOUT_MS = 10000;
const INDEXER_BASE_URL =
  process.env.EXPO_PUBLIC_INDEXER_BASE_URL || process.env.EXPO_PUBLIC_BACKEND_BASE_URL || '';
const INDEXER_HISTORY_PATH = process.env.EXPO_PUBLIC_INDEXER_HISTORY_PATH || '/api/v1/transactions';

function normalizeType(rawType: unknown, from: string, to: string, address: string): TransactionType {
  const value = String(rawType || '').toLowerCase();
  if (value === 'sent' || value === 'send' || value === 'outgoing' || value === 'out') {
    return 'sent';
  }

  if (value === 'received' || value === 'receive' || value === 'incoming' || value === 'in') {
    return 'received';
  }

  const normalizedAddress = address.toLowerCase();
  if (from.toLowerCase() === normalizedAddress) {
    return 'sent';
  }

  if (to.toLowerCase() === normalizedAddress) {
    return 'received';
  }

  return 'sent';
}

function normalizeStatus(rawStatus: unknown): TransactionStatus {
  const value = String(rawStatus || '').toLowerCase();

  if (value === 'completed' || value === 'confirmed' || value === 'success' || value === 'succeeded') {
    return 'completed';
  }

  if (value === 'pending' || value === 'queued' || value === 'processing') {
    return 'pending';
  }

  if (value === 'failed' || value === 'reverted' || value === 'error') {
    return 'failed';
  }

  return 'pending';
}

function normalizeTimestamp(rawTimestamp: unknown): number {
  if (typeof rawTimestamp === 'number' && Number.isFinite(rawTimestamp)) {
    return rawTimestamp > 1e12 ? rawTimestamp : rawTimestamp * 1000;
  }

  if (typeof rawTimestamp === 'string') {
    const numeric = Number(rawTimestamp);
    if (!Number.isNaN(numeric)) {
      return numeric > 1e12 ? numeric : numeric * 1000;
    }

    const parsed = Date.parse(rawTimestamp);
    if (!Number.isNaN(parsed)) {
      return parsed;
    }
  }

  return Date.now();
}

function normalizeAmount(rawAmount: unknown): string {
  if (typeof rawAmount === 'number' && Number.isFinite(rawAmount)) {
    return rawAmount.toString();
  }

  if (typeof rawAmount === 'string' && rawAmount.trim().length > 0) {
    return rawAmount;
  }

  return '0';
}

function mapTransaction(raw: unknown, walletAddress: string, defaultChainKey?: string): TransactionRecord | null {
  if (!raw || typeof raw !== 'object') {
    return null;
  }

  const item = raw as Record<string, unknown>;
  const from = String(item.from || item.sender || '').trim();
  const to = String(item.to || item.recipient || '').trim();
  const hash = String(item.hash || item.txHash || item.transactionHash || '').trim();
  const id = String(item.id || item.txId || hash || '').trim();

  if (!id && !hash) {
    return null;
  }

  const tokenSymbol = String(item.tokenSymbol || item.symbol || item.assetSymbol || 'ETH').trim() || 'ETH';
  const tokenName = String(item.token || item.tokenName || item.assetName || tokenSymbol).trim() || tokenSymbol;
  const timestamp = normalizeTimestamp(item.timestamp || item.time || item.createdAt || item.blockTimestamp);

  const normalized: TransactionRecord = {
    id: id || hash,
    type: normalizeType(item.type || item.direction, from, to, walletAddress),
    amount: normalizeAmount(item.amount || item.value || item.amountFormatted),
    token: tokenName,
    tokenSymbol,
    from,
    to,
    timestamp,
    status: normalizeStatus(item.status),
    hash: hash || id,
    network: String(item.network || item.chain || defaultChainKey || '').trim() || undefined,
  };

  const privacyLevel = String(item.privacyLevel || item.privacy || '').toLowerCase();
  if (privacyLevel === 'max' || privacyLevel === 'standard') {
    normalized.privacyLevel = privacyLevel;
  }

  if (item.fee !== undefined && item.fee !== null) {
    normalized.fee = String(item.fee);
  }

  return normalized;
}

function getTransactionsArray(payload: RawResponse | unknown): unknown[] {
  if (Array.isArray(payload)) {
    return payload;
  }

  if (!payload || typeof payload !== 'object') {
    return [];
  }

  const response = payload as RawResponse;
  if (Array.isArray(response.transactions)) {
    return response.transactions;
  }

  if (Array.isArray(response.items)) {
    return response.items;
  }

  if (Array.isArray(response.data?.transactions)) {
    return response.data?.transactions ?? [];
  }

  if (Array.isArray(response.data?.items)) {
    return response.data?.items ?? [];
  }

  return [];
}

function getCursor(payload: RawResponse | unknown): { nextCursor: string | null; hasMore: boolean } {
  if (!payload || typeof payload !== 'object') {
    return { nextCursor: null, hasMore: false };
  }

  const response = payload as RawResponse;
  const nextCursor =
    response.nextCursor ?? response.data?.nextCursor ?? response.pagination?.nextCursor ?? null;
  const hasMore =
    response.hasMore ?? response.data?.hasMore ?? response.pagination?.hasMore ?? Boolean(nextCursor);

  return { nextCursor, hasMore };
}

const getChainTypeFromKey = (key: string | undefined): ChainType | null => {
  if (!key) return null;
  const chainTypeMap: Record<string, ChainType> = {
    ethereum:        'evm',
    polygon:         'evm',
    arbitrum:        'evm',
    sepolia:         'evm',
    solana:          'svm',
    'solana-devnet': 'svm',
    aptos:           'mvm',
    stellar:         'xlm',
    'stellar-testnet':'xlm',
  };
  return chainTypeMap[key] || null;
};

async function fetchBlockchainTransactions(
  address: string,
  chainKey: string,
  cursor: string | undefined,
  limit: number = 20
): Promise<TransactionHistoryPage> {
  const chainType = getChainTypeFromKey(chainKey);

  if (chainType === 'evm') {
    return fetchEvmHistory(address, chainKey, cursor, limit);
  }

  if (chainType === 'svm') {
    return fetchSolanaHistory(address, chainKey, cursor, limit);
  }

  if (chainType === 'xlm') {
    return fetchStellarHistory(address, chainKey, cursor, limit);
  }

  // Fallback for unsupported chains (e.g. mvm/aptos) - return empty for now since indexer is required
  console.warn(`Public indexer not yet implemented for chain type: ${chainType}`);
  return { transactions: [], nextCursor: null, hasMore: false };
}

async function fetchIndexerTransactions(
  address: string,
  chainKey: string | undefined,
  cursor: string | undefined,
  limit: number
): Promise<TransactionHistoryPage> {
  const params = new URLSearchParams();
  params.set('address', address);
  params.set('limit', String(limit));

  if (chainKey) {
    params.set('chain', chainKey);
  }

  if (cursor) {
    params.set('cursor', cursor);
  }

  const normalizedBase = INDEXER_BASE_URL.replace(/\/$/, '');
  const normalizedPath = INDEXER_HISTORY_PATH.startsWith('/')
    ? INDEXER_HISTORY_PATH
    : `/${INDEXER_HISTORY_PATH}`;
  const url = `${normalizedBase}${normalizedPath}?${params.toString()}`;

  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), REQUEST_TIMEOUT_MS);

  try {
    const response = await fetch(url, {
      method: 'GET',
      headers: {
        Accept: 'application/json',
      },
      signal: controller.signal,
    });

    if (!response.ok) {
      throw new Error(`Indexer request failed with status ${response.status}`);
    }

    const payload = (await response.json()) as RawResponse | unknown;
    const rawItems = getTransactionsArray(payload);

    const transactions = rawItems
      .map((raw) => mapTransaction(raw, address, chainKey))
      .filter((item): item is TransactionRecord => item !== null)
      .sort((a, b) => b.timestamp - a.timestamp);

    const { nextCursor, hasMore } = getCursor(payload);

    return {
      transactions,
      nextCursor,
      hasMore,
    };
  } finally {
    clearTimeout(timeoutId);
  }
}

export async function fetchTransactionHistoryPage({
  address,
  chainKey,
  cursor,
  limit = 20,
}: FetchTransactionHistoryParams): Promise<TransactionHistoryPage> {
  if (!address) {
    return {
      transactions: [],
      nextCursor: null,
      hasMore: false,
    };
  }

  const chainType = getChainTypeFromKey(chainKey);
  if (chainType && !validateAddress(address, chainType)) {
    console.warn(`Invalid ${chainType} address format: ${address.substring(0, 10)}...`);
    return {
      transactions: [],
      nextCursor: null,
      hasMore: false,
    };
  }

  if (INDEXER_BASE_URL) {
    try {
      return await fetchIndexerTransactions(address, chainKey, cursor, limit);
    } catch (error) {
      // AbortError = request timed out or was cancelled (expected on devnets / no indexer)
      // Silently fall back to blockchain without polluting console or Sentry.
      const isAbort = error instanceof Error && error.name === 'AbortError';

      if (!isAbort) {
        console.warn('Indexer fetch failed, falling back to blockchain:', error);
        captureError(error instanceof Error ? error : new Error('Indexer fetch failed'), {
          scope: 'transaction-history',
          chain: chainKey,
        });
      }
    }
  }

  if (chainKey) {
    return fetchBlockchainTransactions(address, chainKey, cursor, limit);
  }

  return { transactions: [], nextCursor: null, hasMore: false };
}

export async function fetchPendingTransactions(
  address: string,
  chainKey: string
): Promise<TransactionRecord[]> {
  try {
    const pendingBlock = await poolCall(chainKey, (p) => p.getBlock({ blockTag: 'pending', includeTransactions: true }));
    if (!pendingBlock || !pendingBlock.transactions) return [];

    const pending: TransactionRecord[] = [];
    const lowerAddress = address.toLowerCase();

    for (const tx of pendingBlock.transactions as any[]) {
      try {
        if (tx && tx.from && tx.to) {
          const txHash = tx.hash;
          const fromLower = tx.from.toLowerCase();
          const toLower = tx.to.toLowerCase();

          if (fromLower === lowerAddress || toLower === lowerAddress) {
            pending.push({
              id: txHash,
              type: fromLower === lowerAddress ? 'sent' : 'received',
              amount: formatEther(tx.value),
              token: 'Ether',
              tokenSymbol: 'ETH',
              from: tx.from,
              to: tx.to,
              timestamp: Date.now(),
              status: 'pending',
              hash: txHash,
              network: chainKey,
            });
          }
        }
      } catch {
        continue;
      }
    }

    return pending;
  } catch (error) {
    captureError(error instanceof Error ? error : new Error('Pending tx fetch failed'), {
      scope: 'transaction-history',
      chain: chainKey,
    });
    return [];
  }
}

